--                       total_matches: int,
--                       state_count: int,
--                       by_naics: [{ code, label, count, total_value }],
--                       by_state: [{ state, count, total_value }],
--                       states: string[],
--                       naics_codes: string[]
--                     }

ALTER TABLE company_analyses
