-- ════ 032_user_documents.sql ════
-- 022: User Documents — personal document hub
-- Stores past proposals, capability statements, certs, reference letters, and reusable AI templates.
-- Files live in Supabase Storage bucket `client-docs` under prefix `user-documents/{user_profile_id}/`.

CREATE TABLE IF NOT EXISTS user_documents (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_profile_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT 'other'
        CHECK (category IN ('proposal','capability','cert','reference','template','other')),
    file_url TEXT,              -- public or signed URL; null for AI-generated text templates
    storage_path TEXT,          -- `user-documents/{user_profile_id}/{timestamp}-{name}`
    file_size BIGINT,
    mime_type TEXT,
    content TEXT,               -- for AI-generated templates (no binary file)
    tags TEXT[] DEFAULT '{}',
    linked_pursuit_id UUID REFERENCES user_pursuits(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_user_documents_user ON user_documents(user_profile_id);
CREATE INDEX IF NOT EXISTS idx_user_documents_category ON user_documents(category);
CREATE INDEX IF NOT EXISTS idx_user_documents_tags ON user_documents USING GIN (tags);
CREATE INDEX IF NOT EXISTS idx_user_documents_pursuit ON user_documents(linked_pursuit_id);

ALTER TABLE user_documents ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS user_documents_own ON user_documents;
CREATE POLICY user_documents_own ON user_documents FOR ALL
    USING (user_profile_id IN (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid()))
    WITH CHECK (user_profile_id IN (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid()));


-- ════ 033_naics_market_stats.sql ════
-- Migration 030: per-NAICS market intelligence cache
--
-- Why: the MarketIntelligence reader was calling USASpending.gov live on every
-- opportunity detail render, with a 15s timeout and `.catch(() => null)`. Every
-- slow/failed call silently hid the section. We now pre-compute aggregates for
-- common NAICS codes into this table and read from here; the live call stays as
-- a fallback for niche NAICS.

create table if not exists public.naics_market_stats (
    naics_code text primary key,

    -- Period covered by the aggregate (end_date - years).
    period_years integer not null default 5,
    start_date date not null,
    end_date date not null,

    -- Summary KPIs (match the shape returned by /api/intelligence/market-size).
    total_spend numeric not null default 0,
    avg_yearly_spend numeric not null default 0,
    yoy_growth_pct numeric not null default 0,
    market_trend text not null default 'STABLE', -- GROWING | DECLINING | STABLE

    -- Structured breakdowns (same JSON shape as the live API).
    yearly_spend jsonb not null default '[]'::jsonb,
    top_agencies jsonb not null default '[]'::jsonb,
    top_states jsonb not null default '[]'::jsonb,
    top_sub_agencies jsonb not null default '[]'::jsonb,

    -- Bookkeeping.
    computed_at timestamptz not null default now(),
    refresh_after timestamptz not null default now() + interval '30 days'
);

create index if not exists idx_naics_market_stats_refresh on public.naics_market_stats(refresh_after);

-- RLS: read-only for all authenticated users (aggregate data, not user-specific).
alter table public.naics_market_stats enable row level security;

drop policy if exists "naics_market_stats read" on public.naics_market_stats;
create policy "naics_market_stats read"
    on public.naics_market_stats
    for select
    to authenticated
    using (true);


-- ════ 034_gov_keywords.sql ════
-- ============================================================
-- Migration 034: Government-contracting keyword library
-- ============================================================
-- Why: NAICS alone misses niches (e.g. "body armor" has no dedicated
-- NAICS). We maintain a curated library of contract-relevant keywords
-- mined from existing opportunities (titles + descriptions), and let
-- user profiles pick up to 3 primary + 5 secondary keywords from it.
-- The scorer uses these to (a) substitute weight when NAICS confidence
-- is low, and (b) refine matching on opps where NAICS already matches.
-- ============================================================

create table if not exists public.gov_keywords (
    keyword        text primary key,                  -- canonical lowercase, e.g. "body armor"
    display_label  text not null,                     -- human-cased, e.g. "Body Armor"
    category       text,                              -- 'defense' | 'it' | 'construction' | 'facilities' | ...
    aliases        text[] not null default '{}',      -- variants: ["body armour", "ballistic vest"]
    frequency      integer not null default 0,        -- count across opportunity titles + descriptions
    title_frequency integer not null default 0,       -- higher-signal: mentions in titles only
    source         text not null default 'mined'
        check (source in ('mined', 'ai', 'manual')),
    created_at     timestamptz not null default now(),
    updated_at     timestamptz not null default now()
);

create index if not exists idx_gov_keywords_category on public.gov_keywords(category);
create index if not exists idx_gov_keywords_frequency on public.gov_keywords(frequency desc);
create index if not exists idx_gov_keywords_aliases on public.gov_keywords using gin(aliases);

alter table public.gov_keywords enable row level security;

drop policy if exists "gov_keywords read" on public.gov_keywords;
create policy "gov_keywords read"
    on public.gov_keywords
    for select
    to authenticated
    using (true);

comment on table public.gov_keywords is
    'Curated keyword library for matching companies to federal opportunities. Seeded from opportunity title/description n-grams, optionally clustered via AI. Read-only to authenticated users; writes via service role.';

-- ------------------------------------------------------------
-- user_profiles: primary + secondary keyword selections
-- ------------------------------------------------------------
-- Stored as text[] of canonical keywords (gov_keywords.keyword values).
-- Caps (3 primary, 5 secondary) enforced in the app layer — cheaper
-- to update a cap than to run an ALTER TABLE on a check constraint.

do $$ begin
    alter table public.user_profiles
        add column primary_keywords text[] not null default '{}';
exception when duplicate_column then null;
end $$;

do $$ begin
    alter table public.user_profiles
        add column secondary_keywords text[] not null default '{}';
exception when duplicate_column then null;
end $$;

comment on column public.user_profiles.primary_keywords is
    'Up to 3 canonical keywords (gov_keywords.keyword) representing the company''s strongest capability signals. Used by the scorer at full weight.';
comment on column public.user_profiles.secondary_keywords is
    'Up to 5 canonical keywords (gov_keywords.keyword) for refinement. Used by the scorer at reduced weight (~0.4 of primary).';


-- ════ 035_gov_keywords_user_add.sql ════
-- ============================================================
-- Migration 035: Allow users to add custom keywords to the library
-- ============================================================
-- The KeywordPicker falls back to "Add 'xyz' as new keyword" when a user's
-- search returns zero library matches. This migration lets authenticated
-- users insert rows *only* when source='user' — the curated 'mined' and 'ai'
-- rows still require service-role writes.
-- ============================================================

drop policy if exists "gov_keywords user insert" on public.gov_keywords;
create policy "gov_keywords user insert"
    on public.gov_keywords
    for insert
    to authenticated
    with check (source = 'user');

-- Allow users to update only rows they added. Keeps tweakability without
-- letting anyone rename curated keywords out from under other users.
drop policy if exists "gov_keywords user update" on public.gov_keywords;
create policy "gov_keywords user update"
    on public.gov_keywords
    for update
    to authenticated
    using (source = 'user')
    with check (source = 'user');

-- Track who added the keyword for audit / future moderation.
do $$ begin
    alter table public.gov_keywords add column added_by_user_id uuid references auth.users(id);
exception when duplicate_column then null;
end $$;

create index if not exists idx_gov_keywords_added_by on public.gov_keywords(added_by_user_id) where added_by_user_id is not null;

comment on column public.gov_keywords.added_by_user_id is
    'Auth user who added this keyword (only populated when source = ''user''). Lets us show ownership and filter per-user pending terms.';


-- ════ 036_client_partners.sql ════
-- ============================================================
-- Migration 036: Partner management
-- ============================================================
-- Users can now save partners (from SAM.gov live search or Quick Checker)
-- and tag them as active or potential. Mirrors client_competitors but with
-- a status enum so Partners page can show two lanes.
-- ============================================================

create table if not exists public.client_partners (
    id                 uuid primary key default gen_random_uuid(),
    user_profile_id    uuid not null references public.user_profiles(id) on delete cascade,
    company_name       text not null,
    website            text,
    uei                text,
    naics_codes        text[] not null default '{}',
    status             text not null default 'potential'
        check (status in ('active', 'potential', 'archived')),
    description        text,
    employee_count     text,
    revenue_estimate   text,
    state              text,
    certifications     text[] not null default '{}',
    crawl_data         jsonb not null default '{}'::jsonb,
    notes              text,
    last_analyzed_at   timestamptz,
    created_at         timestamptz not null default now(),
    updated_at         timestamptz not null default now()
);

create index if not exists idx_client_partners_user on public.client_partners(user_profile_id);
create index if not exists idx_client_partners_status on public.client_partners(user_profile_id, status);
create unique index if not exists uq_client_partners_user_uei on public.client_partners(user_profile_id, uei) where uei is not null;
create unique index if not exists uq_client_partners_user_website on public.client_partners(user_profile_id, website) where website is not null;

alter table public.client_partners enable row level security;

drop policy if exists "client_partners read own" on public.client_partners;
create policy "client_partners read own"
    on public.client_partners
    for select
    to authenticated
    using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

drop policy if exists "client_partners insert own" on public.client_partners;
create policy "client_partners insert own"
    on public.client_partners
    for insert
    to authenticated
    with check (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

drop policy if exists "client_partners update own" on public.client_partners;
create policy "client_partners update own"
    on public.client_partners
    for update
    to authenticated
    using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()))
    with check (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

drop policy if exists "client_partners delete own" on public.client_partners;
create policy "client_partners delete own"
    on public.client_partners
    for delete
    to authenticated
    using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

comment on table public.client_partners is
    'User-curated partner list. Seeded from /api/partners/search (SAM.gov) or from Quick Checker analyses. Status=active means actively working together, potential means shortlisted.';


-- ════ 037_user_views.sql ════
-- ============================================================
-- Migration 037: Saved filter views (HubSpot-style)
-- ============================================================
-- Users can save a snapshot of their current filters on /matches or
-- /opportunities and reload it from a tab bar at the top of the list.
-- `filter_state` holds whatever structured filter the page cares about
-- (NAICS, set-aside, state, sort, view mode, column widths/picks, etc.).
-- ============================================================

create table if not exists public.user_views (
    id               uuid primary key default gen_random_uuid(),
    user_profile_id  uuid not null references public.user_profiles(id) on delete cascade,
    page             text not null check (page in ('matches', 'opportunities')),
    name             text not null,
    filter_state     jsonb not null default '{}'::jsonb,
    sort_order       integer not null default 0,
    created_at       timestamptz not null default now(),
    updated_at       timestamptz not null default now()
);

create index if not exists idx_user_views_user_page on public.user_views(user_profile_id, page, sort_order);

alter table public.user_views enable row level security;

drop policy if exists "user_views read own" on public.user_views;
create policy "user_views read own"
    on public.user_views
    for select
    to authenticated
    using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

drop policy if exists "user_views insert own" on public.user_views;
create policy "user_views insert own"
    on public.user_views
    for insert
    to authenticated
    with check (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

drop policy if exists "user_views update own" on public.user_views;
create policy "user_views update own"
    on public.user_views
    for update
    to authenticated
    using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()))
    with check (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

drop policy if exists "user_views delete own" on public.user_views;
create policy "user_views delete own"
    on public.user_views
    for delete
    to authenticated
    using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

comment on table public.user_views is
    'User-saved filter presets for list pages (matches, opportunities). filter_state is opaque JSON — page layer defines the shape.';


-- ════ 038_profile_members.sql ════
-- ============================================================
-- Migration 038: Team members + invitations
-- ============================================================
-- user_profiles represents a company. profile_members lets multiple auth
-- users collaborate on the same company profile with different roles.
-- profile_invitations holds pending invites until the recipient signs up /
-- accepts. Seat limits are enforced at the API layer based on the owner's
-- subscription tier.
-- ============================================================

create table if not exists public.profile_members (
    id               uuid primary key default gen_random_uuid(),
    profile_id       uuid not null references public.user_profiles(id) on delete cascade,
    auth_user_id     uuid not null references auth.users(id) on delete cascade,
    role             text not null default 'member'
        check (role in ('owner', 'admin', 'member', 'viewer')),
    -- Optional per-member feature flags. Admins can toggle individual
    -- features off for restricted members. Keys mirror sidebar sections.
    feature_access   jsonb not null default '{}'::jsonb,
    invited_by       uuid references auth.users(id),
    invited_at       timestamptz not null default now(),
    accepted_at      timestamptz,
    created_at       timestamptz not null default now()
);

create unique index if not exists uq_profile_members_profile_user
    on public.profile_members(profile_id, auth_user_id);
create index if not exists idx_profile_members_user on public.profile_members(auth_user_id);

alter table public.profile_members enable row level security;

-- Members can see their own membership rows.
drop policy if exists "profile_members read own" on public.profile_members;
create policy "profile_members read own"
    on public.profile_members
    for select
    to authenticated
    using (
        auth_user_id = auth.uid()
        or profile_id in (select id from public.user_profiles where auth_user_id = auth.uid())
    );

-- Only the owner (user_profiles.auth_user_id) can mutate membership rows.
drop policy if exists "profile_members write owner" on public.profile_members;
create policy "profile_members write owner"
    on public.profile_members
    for all
    to authenticated
    using (profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()))
    with check (profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));


-- ------------------------------------------------------------
-- profile_invitations — pending invites (before the recipient has an account)
-- ------------------------------------------------------------
create table if not exists public.profile_invitations (
    id               uuid primary key default gen_random_uuid(),
    profile_id       uuid not null references public.user_profiles(id) on delete cascade,
    email            text not null,
    role             text not null default 'member'
        check (role in ('admin', 'member', 'viewer')),
    feature_access   jsonb not null default '{}'::jsonb,
    token            text not null unique,
    invited_by       uuid not null references auth.users(id),
    expires_at       timestamptz not null default now() + interval '14 days',
    accepted_at      timestamptz,
    created_at       timestamptz not null default now()
);

create unique index if not exists uq_profile_invitations_profile_email_pending
    on public.profile_invitations(profile_id, lower(email))
    where accepted_at is null;

create index if not exists idx_profile_invitations_token on public.profile_invitations(token);
create index if not exists idx_profile_invitations_email on public.profile_invitations(lower(email));

alter table public.profile_invitations enable row level security;

-- Owners see their own invitations. The accept endpoint runs as service role.
drop policy if exists "profile_invitations read own" on public.profile_invitations;
create policy "profile_invitations read own"
    on public.profile_invitations
    for select
    to authenticated
    using (profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

drop policy if exists "profile_invitations write owner" on public.profile_invitations;
create policy "profile_invitations write owner"
    on public.profile_invitations
    for all
    to authenticated
    using (profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()))
    with check (profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));

comment on table public.profile_members is
    'Team members for a company profile. Owner sits in user_profiles.auth_user_id; additional members linked here with roles.';
comment on table public.profile_invitations is
    'Pending invitations. Accept endpoint converts to profile_members on signup / existing-user acceptance.';


-- ════ 039_beta_invites.sql ════
-- ============================================================
-- Migration 039: Beta invites
-- ============================================================
-- Admin manually sends beta invitations (e.g. to LinkedIn contacts).
-- Each invite gets a tokenized signup link that pre-fills the signup
-- form and locks the email. Marked claimed when the invitee signs up.
-- ============================================================

create table if not exists public.beta_invites (
    id                uuid primary key default gen_random_uuid(),
    email             text not null,
    recipient_name    text,
    company_name      text,
    personal_note     text,
    token             text not null unique,
    sent_by           uuid references auth.users(id) on delete set null,
    sent_at           timestamptz not null default now(),
    claimed_at        timestamptz,
    claimed_by        uuid references auth.users(id) on delete set null,
    expires_at        timestamptz not null default (now() + interval '30 days'),
    created_at        timestamptz not null default now()
);

create index if not exists idx_beta_invites_token on public.beta_invites(token);
create index if not exists idx_beta_invites_email on public.beta_invites(lower(email));
create index if not exists idx_beta_invites_sent_at on public.beta_invites(sent_at desc);

alter table public.beta_invites enable row level security;

-- No public policies — all access goes through service-key admin endpoints.
-- The public /api/beta-invites/[token] route uses the service client to
-- look up an invite by its unguessable token.

comment on table public.beta_invites is
    'Manual beta invitations sent by admins. Token-based signup prefill.';


-- ════ 039_contractors_usaspending.sql ════
-- ============================================================
-- Migration 039: Contractors — USASpending enrichment fields
-- ============================================================
-- We now populate per-contractor past-award data via USASpending.gov
-- (free API) through /api/intelligence/recipient-awards and a new nightly
-- cron. These columns cache the aggregate breakdowns so list views can
-- show award-count badges without a live USASpending call per row.
-- ============================================================

do $$ begin
    alter table public.contractors add column agency_relationships jsonb default '[]'::jsonb;
exception when duplicate_column then null;
end $$;

do $$ begin
    alter table public.contractors add column naics_awards jsonb default '[]'::jsonb;
exception when duplicate_column then null;
end $$;

do $$ begin
    alter table public.contractors add column last_usaspending_refresh timestamptz;
exception when duplicate_column then null;
end $$;

comment on column public.contractors.agency_relationships is
    'Top 10 awarding agencies for this recipient, shape [{name, amount, count}]. Populated by USASpending nightly cron.';
comment on column public.contractors.naics_awards is
    'Top 10 NAICS codes where this recipient has won awards, shape [{code, description, amount, count}]. Populated by USASpending nightly cron.';
comment on column public.contractors.last_usaspending_refresh is
    'Timestamp of the last USASpending refresh for this contractor. Rows older than 14 days are re-fetched on demand; cron fills in the long tail.';

create index if not exists idx_contractors_last_usaspending_refresh
    on public.contractors(last_usaspending_refresh);


-- ════ 040_teaming_intelligence.sql ════
-- ============================================================
-- Migration 040: Teaming + year-end spend intelligence
-- ============================================================
-- Three complementary tables that extend the Partners/Dashboard
-- with curated teaming data we ingest from external sources:
--
--   tribal_contractors     — SBA-certified 8(a)/HUBZone/tribal/native-owned
--                            firms with full capability narratives, NAICS
--                            arrays, and SBLO-quality contacts. Seeded from a
--                            ~900-row curated list (GovCon Giants, Apr 2026).
--
--   prime_sblos            — Small Business Liaison Officer (SBLO) contacts
--                            at top-tier primes (BAE, Lockheed, Raytheon …).
--                            Used by the Partners → Primes tab and the
--                            subcontracting outreach drafter.
--
--   agency_spend_forecast  — Per-agency unobligated-balance / Q4 year-end
--                            spend forecast rows that feed the dashboard's
--                            "Year-End Spend Radar" widget. One row per
--                            (agency, fiscal_year, fiscal_period).
-- ============================================================

-- ------------------------------------------------------------
-- Tribal / SBA-certified contractor directory
-- ------------------------------------------------------------
create table if not exists public.tribal_contractors (
    uei                       text primary key,
    cage_code                 text,
    business_name             text not null,
    primary_naics_code        text,
    all_naics_codes           text[]  default '{}'::text[],
    small_naics_codes         text[]  default '{}'::text[],
    certifications            text[]  default '{}'::text[],
    contact_name              text,
    contact_email             text,
    address_line_1            text,
    address_line_2            text,
    city                      text,
    state                     text,
    zipcode                   text,
    capabilities_narrative    text,
    capabilities_statement_url text,
    sba_profile_url           text,
    source                    text,
    source_imported_at        timestamptz default now(),
    created_at                timestamptz default now(),
    updated_at                timestamptz default now()
);

create index if not exists idx_tribal_contractors_primary_naics
    on public.tribal_contractors (primary_naics_code);
create index if not exists idx_tribal_contractors_state
    on public.tribal_contractors (state);
create index if not exists idx_tribal_contractors_naics_gin
    on public.tribal_contractors using gin (all_naics_codes);
create index if not exists idx_tribal_contractors_certs_gin
    on public.tribal_contractors using gin (certifications);

comment on table  public.tribal_contractors is
    'SBA-certified (8(a), HUBZone, WOSB, SDVOSB) small businesses curated for teaming suggestions. ~900 rows seeded from GovCon Giants tribal list (Apr 2026).';
comment on column public.tribal_contractors.certifications is
    'Parsed certifications: 8(a), HUBZone, WOSB, EDWOSB, VOSB, SDVOSB, 8(a) JV.';
comment on column public.tribal_contractors.small_naics_codes is
    'Subset of all_naics_codes that qualify under SBA size standards.';

alter table public.tribal_contractors enable row level security;

-- Everyone authenticated can read the directory (it is curated public data).
drop policy if exists "tribal_contractors_select" on public.tribal_contractors;
create policy "tribal_contractors_select" on public.tribal_contractors
    for select using (auth.role() = 'authenticated');

-- Only the service role (cron / admin tools) can write.
drop policy if exists "tribal_contractors_service_write" on public.tribal_contractors;
create policy "tribal_contractors_service_write" on public.tribal_contractors
    for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');


-- ------------------------------------------------------------
-- Prime-contractor SBLO (Small Business Liaison Officer) directory
-- ------------------------------------------------------------
create table if not exists public.prime_sblos (
    id             uuid primary key default gen_random_uuid(),
    agency_scope   text,   -- 'DoD / Cyber', 'Army', 'Air Force', 'MDA', …
    prime_company  text not null,
    sblo_name      text,
    sblo_email     text,
    sblo_phone     text,
    notes          text,
    source         text,
    created_at     timestamptz default now(),
    updated_at     timestamptz default now()
);

create index if not exists idx_prime_sblos_agency_scope on public.prime_sblos (agency_scope);
create index if not exists idx_prime_sblos_prime_company on public.prime_sblos (prime_company);

comment on table public.prime_sblos is
    'Prime contractor Small Business Liaison Officers. Used for subcontracting outreach from Partners → Primes tab.';

alter table public.prime_sblos enable row level security;

drop policy if exists "prime_sblos_select" on public.prime_sblos;
create policy "prime_sblos_select" on public.prime_sblos
    for select using (auth.role() = 'authenticated');

drop policy if exists "prime_sblos_service_write" on public.prime_sblos;
create policy "prime_sblos_service_write" on public.prime_sblos
    for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');


-- ------------------------------------------------------------
-- Agency year-end / Q4 unobligated-balance forecast
-- ------------------------------------------------------------
create table if not exists public.agency_spend_forecast (
    id                        uuid primary key default gen_random_uuid(),
    rank                      int,
    agency_name               text not null,
    fiscal_year               int  not null,
    fiscal_period             text not null default 'Q4',   -- 'Q4', 'December', 'monthly'
    unobligated_balance_usd   bigint,
    hot_naics                 text[] default '{}'::text[],
    hot_opportunities         text,
    why_now                   text,
    source                    text,
    published_at              date,
    created_at                timestamptz default now(),
    updated_at                timestamptz default now(),
    unique (agency_name, fiscal_year, fiscal_period)
);

create index if not exists idx_agency_spend_forecast_fy
    on public.agency_spend_forecast (fiscal_year);
create index if not exists idx_agency_spend_forecast_naics_gin
    on public.agency_spend_forecast using gin (hot_naics);

comment on table public.agency_spend_forecast is
    'Per-agency Q4 unobligated-balance forecast, used by the Year-End Spend Radar widget. One row per (agency, fiscal_year, fiscal_period).';
comment on column public.agency_spend_forecast.unobligated_balance_usd is
    'Estimated dollars authorized but not yet obligated — the "use it or lose it" pool.';

alter table public.agency_spend_forecast enable row level security;

drop policy if exists "agency_spend_forecast_select" on public.agency_spend_forecast;
create policy "agency_spend_forecast_select" on public.agency_spend_forecast
    for select using (auth.role() = 'authenticated');

drop policy if exists "agency_spend_forecast_service_write" on public.agency_spend_forecast;
create policy "agency_spend_forecast_service_write" on public.agency_spend_forecast
    for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');


