-- ════ 042_outreach_prospects.sql ════
-- ============================================================
-- Migration 042: Outreach prospect pipeline
-- ============================================================
-- A separate table from `contractors` because:
--   - contractors is our reference directory (80k rows, mostly inert).
--   - outreach_prospects is an actionable queue with approval workflow,
--     compliance state (opt-outs, bounces), and sequence tracking.
-- Mixing the two risks accidentally emailing 80k random companies.
-- ============================================================

create table if not exists public.outreach_prospects (
    id                 uuid primary key default gen_random_uuid(),

    -- Identity
    uei                text,
    cage_code          text,
    company_name       text not null,
    website            text,
    state              text,
    city               text,

    -- Classification
    naics_codes        text[] not null default '{}',
    certifications     text[] not null default '{}',
    registration_date  date,              -- from SAM entityRegistration.registrationDate

    -- Enriched contact info (filled by enrichment pass)
    primary_email      text,
    primary_name       text,
    primary_title      text,
    primary_phone      text,
    enriched_at        timestamptz,

    -- Pipeline state
    source             text not null default 'sam_new_registration'
        check (source in ('sam_new_registration', 'sam_naics_match', 'manual', 'import')),
    status             text not null default 'pending_review'
        check (status in (
            'pending_review', 'approved', 'rejected',
            'queued', 'sent', 'replied', 'bounced', 'opted_out'
        )),
    match_score        integer default 0,     -- 0-100 fit-to-ICP heuristic
    rejection_reason   text,
    notes              text,

    -- Review trail
    reviewed_by        uuid references auth.users(id),
    reviewed_at        timestamptz,
    discovered_at      timestamptz not null default now(),
    updated_at         timestamptz not null default now(),

    -- Link back to the contractors row when we already know about them.
    contractor_id      uuid references public.contractors(id) on delete set null
);

create unique index if not exists uq_outreach_prospects_uei
    on public.outreach_prospects(uei) where uei is not null;
create index if not exists idx_outreach_prospects_status on public.outreach_prospects(status);
create index if not exists idx_outreach_prospects_naics on public.outreach_prospects using gin(naics_codes);
create index if not exists idx_outreach_prospects_discovered on public.outreach_prospects(discovered_at desc);

alter table public.outreach_prospects enable row level security;

-- Only admins see the prospect queue. Everyone else just sees the approved
-- prospects that surface on their Partners "Suggested" tab — we gate that
-- separately via a policy that exposes only status='approved'.
drop policy if exists "outreach_prospects admin all" on public.outreach_prospects;
create policy "outreach_prospects admin all"
    on public.outreach_prospects
    for all
    to authenticated
    using (
        exists (
            select 1 from public.user_profiles
            where auth_user_id = auth.uid() and account_type = 'admin'
        )
    )
    with check (
        exists (
            select 1 from public.user_profiles
            where auth_user_id = auth.uid() and account_type = 'admin'
        )
    );

drop policy if exists "outreach_prospects approved read" on public.outreach_prospects;
create policy "outreach_prospects approved read"
    on public.outreach_prospects
    for select
    to authenticated
    using (status = 'approved');


-- Opt-out list is honored globally across all sequences + future tables.
create table if not exists public.outreach_optouts (
    id           uuid primary key default gen_random_uuid(),
    email        text not null unique,
    reason       text,
    opted_out_at timestamptz not null default now()
);
create index if not exists idx_outreach_optouts_email on public.outreach_optouts(lower(email));

alter table public.outreach_optouts enable row level security;

drop policy if exists "outreach_optouts admin all" on public.outreach_optouts;
create policy "outreach_optouts admin all"
    on public.outreach_optouts
    for all
    to authenticated
    using (
        exists (
            select 1 from public.user_profiles
            where auth_user_id = auth.uid() and account_type = 'admin'
        )
    )
    with check (
        exists (
            select 1 from public.user_profiles
            where auth_user_id = auth.uid() and account_type = 'admin'
        )
    );

comment on table public.outreach_prospects is
    'Cold-outreach pipeline. Discovered by /api/cron/discover_new_prospects, reviewed by admin, enriched, sent through drip.';
comment on table public.outreach_optouts is
    'Global opt-out list. Any email here is excluded from all future outreach sends.';


-- ════ 043_veteran_discount.sql ════
-- ============================================================
-- Migration 043 — Veteran status + 20% discount eligibility
-- ============================================================
-- Adds explicit veteran flags to user_profiles so we can
--   (a) show the veteran badge in the UI
--   (b) auto-apply the 20% Stripe discount at checkout
--   (c) track verification source (self-declared vs SAM-verified)
--
-- Design note: sba_certifications already stores 'SDVOSB'/'VOSB'
-- after a successful SAM Entity lookup. The columns below are a
-- denormalized view of that for fast lookups + the ability to
-- accept self-declared veterans before they've registered with SAM.

alter table public.user_profiles
    add column if not exists is_veteran_owned        boolean not null default false,
    add column if not exists veteran_cert_type       text,                         -- 'SDVOSB' | 'VOSB' | 'self_declared' | 'manual'
    add column if not exists veteran_verified_at     timestamptz,
    add column if not exists veteran_verified_source text,                         -- 'sam_entity' | 'self_declared' | 'admin'
    add column if not exists veteran_branch          text,                         -- 'army' | 'navy' | 'marines' | 'air_force' | 'space_force' | 'coast_guard'
    add column if not exists veteran_discount_code   text;                         -- Stripe promotion/coupon id actually applied

-- Audit trail for discount grants + SAM re-verifications
create table if not exists public.veteran_verifications (
    id                  uuid primary key default gen_random_uuid(),
    user_profile_id     uuid not null references public.user_profiles(id) on delete cascade,
    source              text not null check (source in ('sam_entity','self_declared','admin')),
    cert_type           text,
    uei                 text,
    sam_certifications  text[],
    raw_response        jsonb,
    created_at          timestamptz not null default now()
);

create index if not exists idx_veteran_verifications_user
    on public.veteran_verifications(user_profile_id, created_at desc);

-- Fast "is this user eligible for the discount?" lookup
create index if not exists idx_user_profiles_veteran
    on public.user_profiles(is_veteran_owned) where is_veteran_owned = true;

comment on column public.user_profiles.is_veteran_owned is
    'True if the user qualifies for the 20% veteran discount. Set by SAM verification or self-declaration.';
comment on column public.user_profiles.veteran_cert_type is
    'SDVOSB | VOSB | self_declared | manual. Drives the veteran badge shown on billing + dashboard.';
comment on column public.user_profiles.veteran_verified_source is
    'sam_entity (verified via SAM), self_declared (user toggled), or admin (granted manually).';

-- RLS: owners can read + update their own veteran fields; everything else inherits existing policies
do $$
begin
    if not exists (
        select 1 from pg_policies
        where schemaname = 'public'
          and tablename  = 'veteran_verifications'
          and policyname = 'owner_select_veteran_verifications'
    ) then
        create policy "owner_select_veteran_verifications"
            on public.veteran_verifications for select
            using (
                user_profile_id in (
                    select id from public.user_profiles where auth_user_id = auth.uid()
                )
            );
    end if;
end
$$;

alter table public.veteran_verifications enable row level security;


-- ════ 044_capture_intelligence.sql ════
-- ============================================================
-- Migration 044 — Capture Intelligence Expansion
-- ============================================================
-- One migration for Sprint 1 + Sprint 2 data expansion. Adds:
--   • labor_rates           (GSA CALC ingestion)
--   • daily_dod_awards      (war.gov daily $7.5M+ DoD contracts)
--   • bid_protests          (GAO Bid Protest decisions)
--   • far_clauses_cache     (eCFR FAR/DFARS clause cache)
--   • federal_hierarchy     (open.gsa.gov FH API snapshot)
--   • capture_briefs        (generated briefs cache — skip re-gen if fresh)
--   • market_watch_searches (saved natural-language searches → weekly digest)
--
-- Also extends tribal_contractors with DSBS fields so the single partner
-- table can hold both the curated seed AND the 300K-row DSBS feed.

-- ------------------------------------------------------------
-- GSA CALC labor rates
-- ------------------------------------------------------------
create table if not exists public.labor_rates (
    id                    bigserial primary key,
    labor_category        text        not null,
    education_level       text,
    min_years_experience  integer,
    contractor_name       text,
    schedule              text,
    sin                   text,
    hourly_rate_year1     numeric(10,2),
    hourly_rate_current   numeric(10,2),
    idv_piid              text,
    business_size         text,
    worksite              text,        -- 'on-site' | 'off-site' | 'both'
    keywords              text,
    source_id             text        not null default 'gsa_calc',
    fetched_at            timestamptz not null default now()
);

create index if not exists idx_labor_rates_category on public.labor_rates using gin (to_tsvector('english', labor_category));
create index if not exists idx_labor_rates_education on public.labor_rates (education_level);
create index if not exists idx_labor_rates_rate on public.labor_rates (hourly_rate_current);

-- ------------------------------------------------------------
-- war.gov Daily DoD Contract Announcements ($7.5M+)
-- ------------------------------------------------------------
create table if not exists public.daily_dod_awards (
    id                uuid primary key default gen_random_uuid(),
    announcement_date date not null,
    contractor_name   text not null,
    contractor_uei    text,
    amount_usd        numeric(15,2),
    location          text,
    agency            text,             -- 'Army' | 'Navy' | 'Air Force' | 'DLA' | 'Missile Defense Agency' | ...
    contract_number   text,
    sow_summary       text,
    source_url        text,
    raw_text          text,
    created_at        timestamptz not null default now()
);

create index if not exists idx_dod_awards_date on public.daily_dod_awards (announcement_date desc);
create index if not exists idx_dod_awards_contractor on public.daily_dod_awards (contractor_uei) where contractor_uei is not null;
create index if not exists idx_dod_awards_agency on public.daily_dod_awards (agency);

-- ------------------------------------------------------------
-- GAO Bid Protests
-- ------------------------------------------------------------
create table if not exists public.bid_protests (
    id             uuid primary key default gen_random_uuid(),
    docket_number  text unique not null,
    protester      text,
    solicitation   text,
    agency         text,
    decision_date  date,
    outcome        text check (outcome in ('sustained','denied','dismissed','withdrawn','pending','other')),
    decision_url   text,
    summary        text,
    related_uei    text,
    created_at     timestamptz not null default now()
);

create index if not exists idx_protests_agency on public.bid_protests (agency);
create index if not exists idx_protests_outcome on public.bid_protests (outcome);
create index if not exists idx_protests_date on public.bid_protests (decision_date desc);
create index if not exists idx_protests_uei on public.bid_protests (related_uei) where related_uei is not null;

-- ------------------------------------------------------------
-- FAR / DFARS Clauses Cache (eCFR)
-- ------------------------------------------------------------
create table if not exists public.far_clauses_cache (
    clause_id      text primary key,           -- e.g. '52.219-14' or 'DFARS 252.204-7012'
    title          text not null,
    body_text      text not null,
    body_html      text,
    section_url    text,
    last_amended   date,
    fetched_at     timestamptz not null default now()
);

-- ------------------------------------------------------------
-- Federal Hierarchy snapshot (open.gsa.gov FH API)
-- ------------------------------------------------------------
create table if not exists public.federal_hierarchy (
    fh_id              text primary key,             -- unique org id from FH API
    org_name           text not null,
    org_type           text,                         -- 'Department' | 'Independent Agency' | 'Sub-tier' | 'Office'
    parent_fh_id       text,
    parent_name        text,
    agency_code        text,
    fpds_code          text,
    dodaac             text,
    status             text,                         -- 'active' | 'inactive'
    address_state      text,
    fetched_at         timestamptz not null default now()
);

create index if not exists idx_fh_parent on public.federal_hierarchy (parent_fh_id);
create index if not exists idx_fh_fpds on public.federal_hierarchy (fpds_code) where fpds_code is not null;
create index if not exists idx_fh_agency on public.federal_hierarchy (agency_code) where agency_code is not null;

-- ------------------------------------------------------------
-- Capture Briefs cache
-- Skip regeneration if a brief <7 days old exists for (opp, user).
-- ------------------------------------------------------------
create table if not exists public.capture_briefs (
    id               uuid primary key default gen_random_uuid(),
    user_profile_id  uuid references public.user_profiles(id) on delete cascade,
    opportunity_id   uuid not null,
    notice_id        text,
    brief_json       jsonb not null,
    pwin_estimate    integer check (pwin_estimate between 0 and 100),
    model_used       text,
    generated_at     timestamptz not null default now()
);

create index if not exists idx_capture_briefs_user_opp
    on public.capture_briefs (user_profile_id, opportunity_id, generated_at desc);

-- ------------------------------------------------------------
-- Market Watch — saved natural-language searches
-- Weekly Sunday digest runs them + emails results
-- ------------------------------------------------------------
create table if not exists public.market_watch_searches (
    id                uuid primary key default gen_random_uuid(),
    user_profile_id   uuid not null references public.user_profiles(id) on delete cascade,
    name              text not null,
    query_text        text not null,
    filters_json      jsonb not null default '{}'::jsonb,
    active            boolean not null default true,
    last_run_at       timestamptz,
    last_result_count integer,
    created_at        timestamptz not null default now()
);

create index if not exists idx_market_watch_user
    on public.market_watch_searches (user_profile_id) where active = true;

-- ------------------------------------------------------------
-- Extend tribal_contractors with DSBS fields (300K-row feed)
-- ------------------------------------------------------------
alter table public.tribal_contractors
    add column if not exists source                  text default 'curated',   -- 'curated' | 'dsbs' | 'sam'
    add column if not exists capability_narrative    text,
    add column if not exists capability_keywords     text[]      default '{}'::text[],
    add column if not exists poc_name                text,
    add column if not exists poc_email               text,
    add column if not exists poc_phone               text,
    add column if not exists year_established        integer,
    add column if not exists employee_count          integer,
    add column if not exists annual_revenue          numeric,
    add column if not exists is_veteran_owned        boolean     default false;

create index if not exists idx_tc_source on public.tribal_contractors (source);
create index if not exists idx_tc_veteran on public.tribal_contractors (is_veteran_owned) where is_veteran_owned = true;
create index if not exists idx_tc_keywords_gin on public.tribal_contractors using gin (capability_keywords);

-- ------------------------------------------------------------
-- RLS
-- ------------------------------------------------------------
alter table public.labor_rates            enable row level security;
alter table public.daily_dod_awards       enable row level security;
alter table public.bid_protests           enable row level security;
alter table public.far_clauses_cache      enable row level security;
alter table public.federal_hierarchy      enable row level security;
alter table public.capture_briefs         enable row level security;
alter table public.market_watch_searches  enable row level security;

-- Read-everywhere policies for reference tables
do $$
begin
    if not exists (select 1 from pg_policies where tablename='labor_rates' and policyname='labor_rates_read') then
        create policy "labor_rates_read" on public.labor_rates for select using (true);
    end if;
    if not exists (select 1 from pg_policies where tablename='daily_dod_awards' and policyname='dod_awards_read') then
        create policy "dod_awards_read" on public.daily_dod_awards for select using (true);
    end if;
    if not exists (select 1 from pg_policies where tablename='bid_protests' and policyname='protests_read') then
        create policy "protests_read" on public.bid_protests for select using (true);
    end if;
    if not exists (select 1 from pg_policies where tablename='far_clauses_cache' and policyname='far_read') then
        create policy "far_read" on public.far_clauses_cache for select using (true);
    end if;
    if not exists (select 1 from pg_policies where tablename='federal_hierarchy' and policyname='fh_read') then
        create policy "fh_read" on public.federal_hierarchy for select using (true);
    end if;

    -- Owner-only policies for user-specific tables
    if not exists (select 1 from pg_policies where tablename='capture_briefs' and policyname='capture_briefs_owner') then
        create policy "capture_briefs_owner" on public.capture_briefs for all
            using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));
    end if;
    if not exists (select 1 from pg_policies where tablename='market_watch_searches' and policyname='market_watch_owner') then
        create policy "market_watch_owner" on public.market_watch_searches for all
            using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));
    end if;
end
$$;


-- ════ 045_recompete_mcp_zapier.sql ════
-- ============================================================
-- Migration 045 — Recompete Radar + Past-Perf + MCP + Zapier
-- ============================================================
-- Supports:
--   • Recompete Radar  → scans FPDS / USASpending for expiring contracts
--                        and scores recompete likelihood (P1 feature)
--   • Past-Performance → synthesized CPARS-proxy rating per UEI, derived
--                        from FPDS modifications + GAO protests + retention
--   • MCP + Zapier     → third-party integration audit trail (API tokens,
--                        outbound webhook subscriptions, delivery log)
--   • Compliance Matrix cache → reuse extracted Section-L/M matrices
--   • Capability Matrix cache → reuse AI company × opp scoring

-- ------------------------------------------------------------
-- Recompete candidates
-- ------------------------------------------------------------
create table if not exists public.recompete_candidates (
    id                    uuid primary key default gen_random_uuid(),
    source_award_id       text,                         -- FPDS award id / USASpending generated_unique_id
    incumbent_uei         text,
    incumbent_name        text,
    agency                text,
    naics_code            text,
    psc_code              text,
    set_aside             text,
    original_award_value  numeric,
    contract_end_date     date,
    months_to_end         integer,
    confidence            text check (confidence in ('high','medium','low')),
    confidence_score      numeric check (confidence_score between 0 and 1),
    reasoning             text,
    matched_sam_notice_id text,                         -- if a new solicitation has dropped
    created_at            timestamptz not null default now(),
    last_refreshed_at     timestamptz not null default now()
);

create unique index if not exists uq_recompete_source_award
    on public.recompete_candidates (source_award_id) where source_award_id is not null;
create index if not exists idx_recompete_agency_naics
    on public.recompete_candidates (agency, naics_code);
create index if not exists idx_recompete_end_date
    on public.recompete_candidates (contract_end_date)
    where contract_end_date is not null;
create index if not exists idx_recompete_confidence
    on public.recompete_candidates (confidence, confidence_score desc);

-- ------------------------------------------------------------
-- Past-performance proxy ratings (CPARS is not public; this is synthesized)
-- ------------------------------------------------------------
create table if not exists public.past_perf_ratings (
    uei                   text primary key,
    contractor_name       text,
    total_contracts       integer,
    total_value_usd       numeric,
    completed_contracts   integer,
    modification_count    integer,
    avg_modifications     numeric,
    extension_ratio       numeric,                      -- option-exercises / completed
    termination_count     integer,
    protest_against_count integer,
    protest_filed_count   integer,
    primary_agencies      text[]       default '{}'::text[],
    repeat_customer_ratio numeric,                      -- % of their awards from top 3 agencies
    rating                text check (rating in ('exceptional','very_good','satisfactory','marginal','unsatisfactory','insufficient_data')),
    rating_score          numeric check (rating_score between 0 and 1),
    reasoning             text,
    computed_at           timestamptz not null default now()
);

create index if not exists idx_past_perf_rating on public.past_perf_ratings (rating);

-- ------------------------------------------------------------
-- Compliance Matrix cache (reuse extraction within 14 days)
-- ------------------------------------------------------------
create table if not exists public.compliance_matrices (
    id                uuid primary key default gen_random_uuid(),
    opportunity_id    uuid not null,
    notice_id         text,
    matrix_json       jsonb not null,                   -- rows: {section, requirement, obligation_verb, owner, status}
    compliance_score  numeric,                          -- % of requirements addressable by user profile
    model_used        text,
    generated_at      timestamptz not null default now()
);

create index if not exists idx_compliance_opp on public.compliance_matrices (opportunity_id, generated_at desc);

-- ------------------------------------------------------------
-- Capability Matrix cache (per user × opp)
-- ------------------------------------------------------------
create table if not exists public.capability_matrices (
    id                uuid primary key default gen_random_uuid(),
    user_profile_id   uuid not null references public.user_profiles(id) on delete cascade,
    opportunity_id    uuid not null,
    matrix_json       jsonb not null,                   -- rows: {factor, user_strength, opp_requirement, gap, mitigation}
    overall_fit       text check (overall_fit in ('strong','moderate','weak','poor')),
    generated_at      timestamptz not null default now()
);

create index if not exists idx_capability_user_opp
    on public.capability_matrices (user_profile_id, opportunity_id, generated_at desc);

-- ------------------------------------------------------------
-- MCP / Zapier API tokens
-- ------------------------------------------------------------
create table if not exists public.api_tokens (
    id              uuid primary key default gen_random_uuid(),
    user_profile_id uuid not null references public.user_profiles(id) on delete cascade,
    token_prefix    text not null,                     -- first 8 chars, for UI display
    token_hash      text not null unique,              -- SHA-256 of full token
    kind            text not null check (kind in ('mcp','zapier','api')),
    label           text,
    last_used_at    timestamptz,
    expires_at      timestamptz,
    revoked_at      timestamptz,
    created_at      timestamptz not null default now()
);

create index if not exists idx_api_tokens_user on public.api_tokens (user_profile_id) where revoked_at is null;

-- ------------------------------------------------------------
-- Webhook endpoints (Zapier-style outbound)
-- ------------------------------------------------------------
create table if not exists public.webhook_endpoints (
    id              uuid primary key default gen_random_uuid(),
    user_profile_id uuid not null references public.user_profiles(id) on delete cascade,
    url             text not null,
    events          text[] not null default '{}'::text[],   -- ['pursuit.added','match.hot','opportunity.dropped']
    secret          text,
    active          boolean not null default true,
    created_at      timestamptz not null default now()
);

create index if not exists idx_webhook_user_active
    on public.webhook_endpoints (user_profile_id) where active = true;

-- ------------------------------------------------------------
-- Webhook delivery log
-- ------------------------------------------------------------
create table if not exists public.webhook_deliveries (
    id              uuid primary key default gen_random_uuid(),
    webhook_id      uuid not null references public.webhook_endpoints(id) on delete cascade,
    event           text not null,
    payload         jsonb not null,
    status_code     integer,
    response_text   text,
    error_message   text,
    attempt         integer not null default 1,
    delivered_at    timestamptz not null default now()
);

create index if not exists idx_webhook_deliveries_wid
    on public.webhook_deliveries (webhook_id, delivered_at desc);

-- ------------------------------------------------------------
-- RLS
-- ------------------------------------------------------------
alter table public.recompete_candidates   enable row level security;
alter table public.past_perf_ratings      enable row level security;
alter table public.compliance_matrices    enable row level security;
alter table public.capability_matrices    enable row level security;
alter table public.api_tokens             enable row level security;
alter table public.webhook_endpoints      enable row level security;
alter table public.webhook_deliveries     enable row level security;

do $$
begin
    -- Reference tables: read-only for all authenticated users
    if not exists (select 1 from pg_policies where tablename='recompete_candidates' and policyname='recompete_read') then
        create policy "recompete_read" on public.recompete_candidates for select using (true);
    end if;
    if not exists (select 1 from pg_policies where tablename='past_perf_ratings' and policyname='past_perf_read') then
        create policy "past_perf_read" on public.past_perf_ratings for select using (true);
    end if;
    if not exists (select 1 from pg_policies where tablename='compliance_matrices' and policyname='compliance_read') then
        create policy "compliance_read" on public.compliance_matrices for select using (true);
    end if;

    -- User-scoped tables
    if not exists (select 1 from pg_policies where tablename='capability_matrices' and policyname='capability_owner') then
        create policy "capability_owner" on public.capability_matrices for all
            using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));
    end if;
    if not exists (select 1 from pg_policies where tablename='api_tokens' and policyname='api_tokens_owner') then
        create policy "api_tokens_owner" on public.api_tokens for all
            using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));
    end if;
    if not exists (select 1 from pg_policies where tablename='webhook_endpoints' and policyname='webhooks_owner') then
        create policy "webhooks_owner" on public.webhook_endpoints for all
            using (user_profile_id in (select id from public.user_profiles where auth_user_id = auth.uid()));
    end if;
    if not exists (select 1 from pg_policies where tablename='webhook_deliveries' and policyname='webhook_deliveries_owner') then
        create policy "webhook_deliveries_owner" on public.webhook_deliveries for select
            using (webhook_id in (
                select id from public.webhook_endpoints where user_profile_id in (
                    select id from public.user_profiles where auth_user_id = auth.uid()
                )
            ));
    end if;
end
$$;


-- ════ 046_forecast_change_detection.sql ════
-- ============================================================
-- Migration 046 — Agency Forecast Change Detection
-- ============================================================
-- Tracks federal-agency procurement forecast pages. When a new line item
-- appears we record it (matched against user NAICS for targeted alerts).
-- Powered by a cron that polls changedetection.io (self-hosted) OR an
-- internal lightweight differ that hashes the forecast-table content
-- per run. Either way, the schema is the same.

create table if not exists public.agency_forecast_sources (
    id               uuid primary key default gen_random_uuid(),
    agency           text not null,                      -- e.g. "Department of Veterans Affairs"
    agency_code      text,                               -- FPDS code, if known
    label            text not null,                      -- "VA OSDBU Quarterly Forecast FY26 Q3"
    url              text not null unique,
    selector         text,                               -- optional CSS/XPath for changedetection.io
    changedetection_watch_id text,                       -- external service id if using cd.io
    last_checked_at  timestamptz,
    last_hash        text,                               -- SHA-256 of the normalized content
    active           boolean not null default true,
    created_at       timestamptz not null default now()
);

create index if not exists idx_forecast_sources_agency on public.agency_forecast_sources (agency);

create table if not exists public.agency_forecast_changes (
    id               uuid primary key default gen_random_uuid(),
    source_id        uuid not null references public.agency_forecast_sources(id) on delete cascade,
    detected_at      timestamptz not null default now(),
    diff_summary     text,
    added_lines      text[]      default '{}'::text[],
    removed_lines    text[]      default '{}'::text[],
    naics_detected   text[]      default '{}'::text[],
    raw_snippet      text,
    notified_users   uuid[]      default '{}'::uuid[]
);

create index if not exists idx_forecast_changes_source on public.agency_forecast_changes (source_id, detected_at desc);
create index if not exists idx_forecast_changes_naics_gin on public.agency_forecast_changes using gin (naics_detected);

alter table public.agency_forecast_sources enable row level security;
alter table public.agency_forecast_changes enable row level security;

do $$
begin
    if not exists (select 1 from pg_policies where tablename='agency_forecast_sources' and policyname='sources_read') then
        create policy "sources_read" on public.agency_forecast_sources for select using (true);
    end if;
    if not exists (select 1 from pg_policies where tablename='agency_forecast_changes' and policyname='changes_read') then
        create policy "changes_read" on public.agency_forecast_changes for select using (true);
    end if;
end
$$;

