insert into public.agency_forecast_sources (agency, agency_code, label, url)
values
    ('Department of Veterans Affairs', '36', 'VA OSDBU Forecast of Contracting Opportunities', 'https://www.vendorportal.ecms.va.gov/FBODocumentServer/DocumentServer.aspx?DocumentId=forecast'),
    ('Department of Defense',          '97', 'DoD SB Forecast (OSBP)', 'https://business.defense.gov/Small-Business/Forecast/'),
    ('General Services Administration','47', 'GSA OSDBU Forecast', 'https://www.gsa.gov/small-business/small-business-resources/forecast-of-opportunities'),
    ('Department of Energy',           '89', 'DOE OSDBU Forecast',  'https://www.energy.gov/osdbu/acquisition-forecast'),
    ('Department of Homeland Security','70', 'DHS ACQUISITION Forecast','https://apfs-cloud.dhs.gov/')
on conflict (url) do nothing;


-- ════ 047_fpds_awards.sql ════
-- ============================================================
-- Migration 047 — FPDS Awards (federal contract actions)
-- ============================================================
-- FPDS (fpds.gov) is the authoritative record of every federal contract
-- action. We pull the Atom feed and store awards + modifications keyed by
-- piid + referenced_idv + modification_number so we can:
--   1. Power the Past-Performance proxy with real mod counts + extensions
--   2. Detect terminations (contract_action_type IN ('DCA','TCA','TFC'))
--   3. Surface incumbent award histories on opportunity detail pages
--
-- The fpds Python package or our tools/26_ingest_fpds.mjs populate this.
-- No PK on a single column because FPDS's natural key is composite:
-- (piid, referenced_idv, modification_number).

create table if not exists public.fpds_awards (
    id                    uuid primary key default gen_random_uuid(),
    piid                  text not null,
    referenced_idv        text,
    modification_number   text,
    contractor_uei        text,
    contractor_name       text,
    awarding_agency       text,
    awarding_sub_agency   text,
    naics_code            text,
    psc_code              text,
    set_aside             text,

    -- Dollar values
    obligation_amount     numeric(15,2),
    base_and_exercised    numeric(15,2),
    base_and_all_options  numeric(15,2),

    -- Dates
    signed_date           date,
    effective_date        date,
    current_end_date      date,
    ultimate_end_date     date,

    -- Action type — drives past-perf signal extraction
    contract_action_type  text,                       -- 'A'|'IDV'|'IDC'|'DCA'(default)|'TCA'|'TFC' etc.
    idv_type              text,
    contract_type         text,
    type_of_contract_pricing text,

    -- Competition
    extent_competed       text,
    solicitation_procedures text,
    number_of_offers_received integer,

    -- Derived flags for fast queries
    is_termination        boolean generated always as (
        contract_action_type in ('DCA','TCA','TFC')
    ) stored,
    is_option_exercise    boolean generated always as (
        contract_action_type = 'B'
    ) stored,
    is_modification       boolean generated always as (
        modification_number is not null and modification_number <> '0' and modification_number <> ''
    ) stored,

    source_url            text,
    raw_xml_hash          text,
    fetched_at            timestamptz not null default now()
);

-- Natural uniqueness for upserts
create unique index if not exists uq_fpds_natural
    on public.fpds_awards (piid, coalesce(referenced_idv, ''), coalesce(modification_number, ''));

create index if not exists idx_fpds_uei on public.fpds_awards (contractor_uei);
create index if not exists idx_fpds_agency_naics on public.fpds_awards (awarding_agency, naics_code);
create index if not exists idx_fpds_signed_date on public.fpds_awards (signed_date desc);
create index if not exists idx_fpds_uei_mod on public.fpds_awards (contractor_uei) where is_modification = true;
create index if not exists idx_fpds_uei_term on public.fpds_awards (contractor_uei) where is_termination = true;

alter table public.fpds_awards enable row level security;

do $$
begin
    if not exists (select 1 from pg_policies where tablename='fpds_awards' and policyname='fpds_read') then
        create policy "fpds_read" on public.fpds_awards for select using (true);
    end if;
end $$;


-- ════ 048_slack_installations.sql ════
-- ============================================================
-- Migration 048 — Slack workspace installations
-- ============================================================
-- One row per Slack workspace that has installed the CapturePilot app.
-- Mapping is keyed by Slack team_id so the events handler can resolve
-- the right CapturePilot user_profile for slash commands + mentions.
--
-- Tokens are stored encrypted at rest (pgsodium) when available; for the
-- MVP we keep them as plain text behind service-role-only RLS.

create table if not exists public.slack_installations (
    id                  uuid primary key default gen_random_uuid(),
    team_id             text not null unique,        -- Slack team/workspace id (e.g. "T0A1B2C3")
    team_name           text,
    enterprise_id       text,
    enterprise_name     text,
    bot_user_id         text,                        -- Slack bot user id (U...)
    bot_token           text,                        -- xoxb- token used by chat.postMessage etc.
    user_id             text,                        -- Slack user id of the installer
    installer_email     text,
    scopes              text[]      default '{}'::text[],
    user_profile_id     uuid references public.user_profiles(id) on delete set null,
    app_id              text,
    installed_at        timestamptz not null default now(),
    uninstalled_at      timestamptz,
    last_used_at        timestamptz,
    raw_response        jsonb
);

create index if not exists idx_slack_user_profile on public.slack_installations (user_profile_id);
create index if not exists idx_slack_team_active on public.slack_installations (team_id) where uninstalled_at is null;

alter table public.slack_installations enable row level security;

do $$
begin
    if not exists (select 1 from pg_policies where tablename='slack_installations' and policyname='slack_owner_select') then
        create policy "slack_owner_select" on public.slack_installations for select
            using (user_profile_id in (
                select id from public.user_profiles where auth_user_id = auth.uid()
            ));
    end if;
end $$;


-- ════ 049_academy_updates_admin_pushes.sql ════
-- ============================================================
-- Migration 049 — Academy + Product Updates + Admin Opportunity Pushes
-- ============================================================
-- Three loosely-related additions:
--   1. academy_articles — ungated learning library surfaced inside the app,
--      teased on the marketing site as lead magnets.
--   2. release_notes — "What we're building" timeline. Public on the website,
--      rendered as a vertical changelog feed.
--   3. admin_opportunity_pushes — audit trail for when Andre / an admin
--      hand-picks an opportunity and pushes it into an agency client's
--      pipeline. Paired with a pipeline_activity entry + customer email.

-- ------------------------------------------------------------
-- academy_articles
-- ------------------------------------------------------------
create table if not exists public.academy_articles (
    id             uuid primary key default gen_random_uuid(),
    slug           text not null unique,
    title          text not null,
    excerpt        text,
    body_md        text not null,                    -- Markdown body; rendered server-side for SEO
    category       text not null default 'playbook', -- 'playbook' | 'cert' | 'proposal' | 'pricing' | 'market_intel'
    reading_minutes integer,
    featured       boolean not null default false,
    teaser_public  boolean not null default true,    -- If true, title + excerpt appear on the website (body stays app-only)
    cover_image_url text,
    author_name    text default 'CapturePilot Team',
    published_at   timestamptz,
    updated_at     timestamptz not null default now(),
    created_at     timestamptz not null default now()
);

create index if not exists idx_academy_published on public.academy_articles (published_at desc) where published_at is not null;
create index if not exists idx_academy_category on public.academy_articles (category);

-- ------------------------------------------------------------
-- release_notes
-- ------------------------------------------------------------
create table if not exists public.release_notes (
    id             uuid primary key default gen_random_uuid(),
    version        text,                             -- optional semantic version
    title          text not null,
    summary        text not null,                    -- 1-3 sentences — public-facing, tease without revealing moat
    category       text not null default 'feature',  -- 'feature' | 'fix' | 'performance' | 'integration'
    highlights     text[] default '{}'::text[],      -- bullet list shown under the title
    shipped_at     timestamptz not null default now(),
    is_public      boolean not null default true,
    commit_sha     text,                             -- optional git sha pointer for internal reference
    created_at     timestamptz not null default now()
);

create index if not exists idx_release_notes_shipped on public.release_notes (shipped_at desc);
create index if not exists idx_release_notes_public on public.release_notes (shipped_at desc) where is_public = true;

-- ------------------------------------------------------------
-- admin_opportunity_pushes
-- ------------------------------------------------------------
create table if not exists public.admin_opportunity_pushes (
    id             uuid primary key default gen_random_uuid(),
    user_profile_id uuid not null references public.user_profiles(id) on delete cascade,
    opportunity_id uuid not null,
    pursuit_id     uuid,                             -- populated after pursuit row is created
    pushed_by_user_id uuid references auth.users(id),
    pushed_by_name text default 'Americurial Team',
    notes          text,                             -- internal context
    customer_message text,                           -- free-form message shown in the email to the client
    email_sent_at  timestamptz,
    created_at     timestamptz not null default now()
);

create index if not exists idx_admin_pushes_user on public.admin_opportunity_pushes (user_profile_id, created_at desc);

-- ------------------------------------------------------------
-- RLS
-- ------------------------------------------------------------
alter table public.academy_articles            enable row level security;
alter table public.release_notes               enable row level security;
alter table public.admin_opportunity_pushes    enable row level security;

do $$
begin
    -- Academy: full content readable to any signed-in user; teaser subset is
    -- handled by the public /api/academy endpoint which uses service key.
    if not exists (select 1 from pg_policies where tablename='academy_articles' and policyname='academy_read_auth') then
        create policy "academy_read_auth" on public.academy_articles for select
            using (auth.uid() is not null);
    end if;

    -- Release notes: public-readable if is_public = true
    if not exists (select 1 from pg_policies where tablename='release_notes' and policyname='release_notes_public') then
        create policy "release_notes_public" on public.release_notes for select
            using (is_public = true);
    end if;

    -- Admin pushes: owner (customer) can read their own
    if not exists (select 1 from pg_policies where tablename='admin_opportunity_pushes' and policyname='pushes_owner_read') then
        create policy "pushes_owner_read" on public.admin_opportunity_pushes for select
            using (user_profile_id in (
                select id from public.user_profiles where auth_user_id = auth.uid()
            ));
    end if;
end $$;

