-- ════ 054_fix_rls_coverage.sql ════
-- ============================================================
-- Migration 054 — Fix RLS policy coverage gaps
-- ============================================================
-- Context: the event-trigger rls_auto_enable() enables RLS on every new table,
-- but several tables never had policies added, so they became effectively
-- inaccessible to every role except service_role. Discovered via pg_dump on
-- 2026-04-22: these tables have ENABLE ROW LEVEL SECURITY but 0 policies.
--
-- Affected tables:
--   contacts            (91K SAM POC contact rows — public federal data)
--   agencies            (reference lookup)
--   archive_types       (reference lookup)
--   opportunity_types   (reference lookup)
--   capture_outcomes    (per-user outcome logs — owner-scoped)
--
-- The app works today only because every server-side query uses the service
-- role key (which bypasses RLS). Adding these policies is additive and safe.
-- ============================================================

-- ------------------------------------------------------------
-- Reference data — readable by any authenticated user.
-- (These are federal public-record lookups, not user-private.)
-- ------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'contacts' AND policyname = 'contacts_read_auth') THEN
        CREATE POLICY contacts_read_auth ON public.contacts
            FOR SELECT TO authenticated USING (true);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'agencies' AND policyname = 'agencies_read_auth') THEN
        CREATE POLICY agencies_read_auth ON public.agencies
            FOR SELECT TO authenticated USING (true);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'archive_types' AND policyname = 'archive_types_read_auth') THEN
        CREATE POLICY archive_types_read_auth ON public.archive_types
            FOR SELECT TO authenticated USING (true);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'opportunity_types' AND policyname = 'opportunity_types_read_auth') THEN
        CREATE POLICY opportunity_types_read_auth ON public.opportunity_types
            FOR SELECT TO authenticated USING (true);
    END IF;
END $$;

-- ------------------------------------------------------------
-- capture_outcomes — admin-only.
-- Not user-scoped (keyed on opportunity_id + contractor_id). Used by the
-- internal capture pipeline to track bid/win/loss outcomes per contractor.
-- ------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'capture_outcomes' AND policyname = 'capture_outcomes_admin') THEN
        CREATE POLICY capture_outcomes_admin ON public.capture_outcomes
            FOR ALL TO authenticated
            USING (
                EXISTS (
                    SELECT 1 FROM public.user_profiles
                    WHERE user_profiles.id = auth.uid()
                    AND user_profiles.account_type = 'admin'
                )
            )
            WITH CHECK (
                EXISTS (
                    SELECT 1 FROM public.user_profiles
                    WHERE user_profiles.id = auth.uid()
                    AND user_profiles.account_type = 'admin'
                )
            );
    END IF;
END $$;

-- Service role bypasses RLS on all of the above automatically; no explicit
-- service_role policy is required.


-- ════ 055_gsa_schedule_and_subawards.sql ════
-- ============================================================
-- Migration 055 — GSA Schedule holders + USASpending sub-awards
-- ============================================================
-- Two new tables to close the teaming-intelligence gaps identified on
-- 2026-04-22:
--   1. gsa_schedule_holders — companies on GSA MAS contracts (who can we
--      team with, who sells at what ceiling rate). Populated daily from
--      GSA eLibrary + GSA Advantage scrapes.
--   2. subaward_edges — prime → sub relationships pulled from
--      USASpending sub-awards API. The missing sub-contracting graph.
-- ============================================================

-- ------------------------------------------------------------
-- gsa_schedule_holders
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.gsa_schedule_holders (
    id            uuid PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),
    contract_no   text NOT NULL,
    company_name  text NOT NULL,
    uei           text,
    duns          text,
    cage_code     text,
    schedule      text,             -- e.g. "MAS", "IT Schedule 70"
    sin_codes     text[] DEFAULT '{}'::text[],
    naics_codes   text[] DEFAULT '{}'::text[],
    small_business boolean DEFAULT false,
    certifications text[] DEFAULT '{}'::text[],  -- 8(a), HUBZone, SDVOSB, WOSB
    phone         text,
    email         text,
    website       text,
    address       text,
    state         text,
    contract_start_date date,
    contract_end_date   date,
    ceiling_value       numeric,
    source        text DEFAULT 'gsa_elibrary',
    created_at    timestamptz DEFAULT now(),
    updated_at    timestamptz DEFAULT now(),
    UNIQUE (contract_no, company_name)
);

CREATE INDEX IF NOT EXISTS idx_gsa_holders_uei            ON public.gsa_schedule_holders (uei);
CREATE INDEX IF NOT EXISTS idx_gsa_holders_state          ON public.gsa_schedule_holders (state);
CREATE INDEX IF NOT EXISTS idx_gsa_holders_naics_gin      ON public.gsa_schedule_holders USING gin (naics_codes);
CREATE INDEX IF NOT EXISTS idx_gsa_holders_sin_gin        ON public.gsa_schedule_holders USING gin (sin_codes);
CREATE INDEX IF NOT EXISTS idx_gsa_holders_certs_gin      ON public.gsa_schedule_holders USING gin (certifications);

-- ------------------------------------------------------------
-- subaward_edges (USASpending sub-award graph)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.subaward_edges (
    id              uuid PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),
    prime_uei       text NOT NULL,
    prime_name      text,
    sub_uei         text NOT NULL,
    sub_name        text,
    prime_award_id  text,            -- USASpending contract PIID
    subaward_amount numeric,
    subaward_date   date,
    naics_code      text,
    agency          text,
    description     text,
    source          text DEFAULT 'usaspending_api',
    fetched_at      timestamptz DEFAULT now(),
    UNIQUE (prime_uei, sub_uei, prime_award_id, subaward_date)
);

CREATE INDEX IF NOT EXISTS idx_subawards_prime_uei    ON public.subaward_edges (prime_uei);
CREATE INDEX IF NOT EXISTS idx_subawards_sub_uei      ON public.subaward_edges (sub_uei);
CREATE INDEX IF NOT EXISTS idx_subawards_agency       ON public.subaward_edges (agency);
CREATE INDEX IF NOT EXISTS idx_subawards_date         ON public.subaward_edges (subaward_date DESC);

-- ------------------------------------------------------------
-- RLS — both tables are public reference data for authenticated users
-- ------------------------------------------------------------
ALTER TABLE public.gsa_schedule_holders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subaward_edges       ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='gsa_schedule_holders' AND policyname='gsa_holders_read_auth') THEN
        CREATE POLICY gsa_holders_read_auth ON public.gsa_schedule_holders
            FOR SELECT TO authenticated USING (true);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='subaward_edges' AND policyname='subawards_read_auth') THEN
        CREATE POLICY subawards_read_auth ON public.subaward_edges
            FOR SELECT TO authenticated USING (true);
    END IF;
END $$;


-- ════ 056_background_jobs.sql ════
-- ============================================================
-- Migration 056 — generic background_jobs table
-- ============================================================
-- One row per long-running async task (AI win strategy, voice brief,
-- compliance matrix, capability matrix, capture brief, bulk recrawl, etc).
-- The client polls the row every 2s and renders a step-by-step progress UI.
-- Jobs persist across navigation so the user can start a long-running task,
-- tab away, and come back to see progress (or the final result).
-- ============================================================

CREATE TABLE IF NOT EXISTS public.background_jobs (
    id              uuid PRIMARY KEY DEFAULT extensions.uuid_generate_v4(),
    user_profile_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,

    -- Dispatch
    kind            text NOT NULL,                                         -- 'ai_win_strategy' | 'voice_brief' | 'compliance_matrix' | ...
    title           text,                                                  -- human-readable title for the indicator pill
    status          text NOT NULL DEFAULT 'pending',                       -- pending | running | completed | failed | canceled
    opportunity_id  uuid REFERENCES public.opportunities(id) ON DELETE SET NULL,
    notice_id       text,

    -- Progress
    steps           jsonb DEFAULT '[]'::jsonb,                             -- [{key,label,status,started_at,duration_ms,detail}]
    current_step    text,
    completed_steps integer DEFAULT 0,
    total_steps     integer DEFAULT 0,
    progress_pct    integer DEFAULT 0 CHECK (progress_pct BETWEEN 0 AND 100),

    -- Output
    result          jsonb,
    error           text,

    -- Timing
    started_at      timestamptz,
    completed_at    timestamptz,
    created_at      timestamptz DEFAULT now() NOT NULL,
    updated_at      timestamptz DEFAULT now() NOT NULL,

    CONSTRAINT bg_jobs_status_check CHECK (
        status IN ('pending','running','completed','failed','canceled')
    )
);

CREATE INDEX IF NOT EXISTS idx_bg_jobs_user_status  ON public.background_jobs (user_profile_id, status);
CREATE INDEX IF NOT EXISTS idx_bg_jobs_updated      ON public.background_jobs (updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_bg_jobs_kind         ON public.background_jobs (kind, status);

-- Touch updated_at on update
CREATE OR REPLACE FUNCTION public.touch_background_jobs_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS trg_background_jobs_touch ON public.background_jobs;
CREATE TRIGGER trg_background_jobs_touch
    BEFORE UPDATE ON public.background_jobs
    FOR EACH ROW EXECUTE FUNCTION public.touch_background_jobs_updated_at();

ALTER TABLE public.background_jobs ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'background_jobs' AND policyname = 'bg_jobs_owner_select') THEN
        CREATE POLICY bg_jobs_owner_select ON public.background_jobs
            FOR SELECT TO authenticated
            USING (user_profile_id IN (SELECT id FROM public.user_profiles WHERE auth_user_id = auth.uid()));
    END IF;
END $$;


-- ════ 057_pg_cron_triggers.sql ════
-- ============================================================
-- Migration 057 — pg_cron + pg_net triggers for bulk enrichment
-- ============================================================
-- Why: Vercel's cron scheduler silently failed to register the
--      bulk_enrich_* crons added in vercel.json. Supabase pg_cron
--      fires the same routes reliably every 15/30 min.
--
-- Prereq (already applied via MCP in this session):
--   CREATE EXTENSION pg_cron;
--   CREATE EXTENSION pg_net;
--
-- Manual step after apply: insert the service key once:
--   INSERT INTO public.internal_config (key, value)
--   VALUES ('supabase_service_key', '<paste service role JWT>')
--   ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
-- ============================================================

CREATE TABLE IF NOT EXISTS public.internal_config (
    key        text PRIMARY KEY,
    value      text NOT NULL,
    updated_at timestamptz DEFAULT now()
);
ALTER TABLE public.internal_config ENABLE ROW LEVEL SECURITY;
-- No policies — only service_role can read (bypasses RLS).

CREATE OR REPLACE FUNCTION public.trigger_cron_route(route_path text)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
    base_url text := 'https://app.capturepilot.com';
    svc_key  text;
    req_id   bigint;
BEGIN
    SELECT value INTO svc_key FROM public.internal_config WHERE key = 'supabase_service_key';
    IF svc_key IS NULL THEN
        RAISE NOTICE 'No supabase_service_key configured; skipping %', route_path;
        RETURN NULL;
    END IF;
    SELECT net.http_get(
        url                  := base_url || route_path,
        headers              := jsonb_build_object('Authorization', 'Bearer ' || svc_key),
        timeout_milliseconds := 280000
    ) INTO req_id;
    RETURN req_id;
END $$;

-- Schedule the 4 enrichment crons from Supabase (idempotent).
DO $$
BEGIN
    PERFORM cron.unschedule('bulk_enrich_descriptions') WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='bulk_enrich_descriptions');
    PERFORM cron.unschedule('bulk_enrich_ai')           WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='bulk_enrich_ai');
    PERFORM cron.unschedule('enrich_apollo')            WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='enrich_apollo');
    PERFORM cron.unschedule('naics_stats_weekly')       WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='naics_stats_weekly');
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

SELECT cron.schedule('bulk_enrich_descriptions', '*/15 * * * *',
    $JOB$SELECT public.trigger_cron_route('/api/cron/bulk_enrich_descriptions');$JOB$);
SELECT cron.schedule('bulk_enrich_ai',           '*/30 * * * *',
    $JOB$SELECT public.trigger_cron_route('/api/cron/bulk_enrich_ai');$JOB$);
SELECT cron.schedule('enrich_apollo',            '30 */2 * * *',
    $JOB$SELECT public.trigger_cron_route('/api/cron/enrich_apollo_contractors');$JOB$);
SELECT cron.schedule('naics_stats_weekly',       '0 3 * * 0',
    $JOB$SELECT public.trigger_cron_route('/api/cron/naics_stats_backfill');$JOB$);


-- ════ 058_cleanup_audit_and_safeguards.sql ════
-- 058_cleanup_audit_and_safeguards.sql
--
-- Audit log for opportunity lifecycle cleanup + a view of hard-delete candidates
-- that respects user-invested data (pursuits, HOT/WARM matches, extracted
-- attachments). The cleanup cron queries this view instead of opportunities
-- directly, so protected rows are never deleted.

create table if not exists public.cleanup_log (
    id            bigserial primary key,
    run_at        timestamptz not null default now(),
    kind          text not null,              -- 'archived_delete' | 'intelligence_delete' | 'status_transition' | ...
    row_count     integer not null default 0,
    opportunity_ids uuid[] not null default '{}',
    notes         jsonb not null default '{}'::jsonb
);

create index if not exists cleanup_log_run_at_idx on public.cleanup_log (run_at desc);
create index if not exists cleanup_log_kind_idx   on public.cleanup_log (kind);

alter table public.cleanup_log enable row level security;

-- Only service role reads (cron writes, admins query via API)
drop policy if exists cleanup_log_service_all on public.cleanup_log;
create policy cleanup_log_service_all on public.cleanup_log
    for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');

-- View: ARCHIVED rows genuinely safe to hard-delete. Preserves anything a user
-- invested effort in (pursuits, saved matches, extracted attachment text).
create or replace view public.opportunities_deletable_archived as
select o.id
from public.opportunities o
where o.status = 'ARCHIVED'
  and o.retention_protected = false
  and o.status_changed_at < (now() - interval '365 days')
  and not exists (select 1 from public.user_pursuits up where up.opportunity_id = o.id)
  and not exists (
    select 1 from public.user_matches um
    where um.opportunity_id = o.id
      and (um.classification in ('HOT', 'WARM') or um.is_saved = true)
  )
  and not exists (
    select 1 from public.opportunity_attachments oa
    where oa.opportunity_id = o.id
      and oa.extracted_text is not null
      and length(oa.extracted_text) > 500
  );

-- View: INTELLIGENCE rows safe to hard-delete (old sources-sought w/ no linked
-- solicitation and no user investment).
create or replace view public.opportunities_deletable_intelligence as
select o.id
from public.opportunities o
where o.status = 'INTELLIGENCE'
  and o.retention_protected = false
  and o.posted_date < (now() - interval '730 days')
  and o.related_notice_id is null
  and not exists (select 1 from public.user_pursuits up where up.opportunity_id = o.id)
  and not exists (
    select 1 from public.user_matches um
    where um.opportunity_id = o.id
      and (um.classification in ('HOT', 'WARM') or um.is_saved = true)
  );

grant select on public.opportunities_deletable_archived to service_role;
grant select on public.opportunities_deletable_intelligence to service_role;


-- ════ 059_pg_cron_cleanup_and_analyze.sql ════
-- 059_pg_cron_cleanup_and_analyze.sql
--
-- Backup schedules in pg_cron for db_cleanup (weekly) and analyze_match_attachments
-- (every 20 min). Vercel's cron has been unreliable — pg_cron fires the same
-- routes reliably with the service-key bearer path.
--
-- Prereq: migration 057 created internal_config + trigger_cron_route().

DO $$
BEGIN
    PERFORM cron.unschedule('db_cleanup_weekly')          WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='db_cleanup_weekly');
    PERFORM cron.unschedule('analyze_match_attachments')  WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='analyze_match_attachments');
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

-- Sunday 04:00 UTC — same slot as vercel.json, acts as redundant trigger
SELECT cron.schedule('db_cleanup_weekly', '0 4 * * 0',
    $JOB$SELECT public.trigger_cron_route('/api/cron/db_cleanup');$JOB$);

-- Every 20 min — processes 4 opps × 3 docs = 12 SAM docs/run
SELECT cron.schedule('analyze_match_attachments', '*/20 * * * *',
    $JOB$SELECT public.trigger_cron_route('/api/cron/analyze_match_attachments');$JOB$);


-- ════ 060_academy_videos.sql ════
-- ============================================================
-- Migration 060 — Academy: video support + admin CMS scaffolding
-- ============================================================
-- Lets admins publish videos alongside markdown articles. Keeps the existing
-- schema backward-compatible: old rows default to content_type='article',
-- body_md becomes optional (videos don't need it), video_* fields are null.

alter table public.academy_articles
    add column if not exists content_type     text not null default 'article',
    add column if not exists video_url        text,
    add column if not exists video_provider   text,
    add column if not exists video_embed_id   text,
    add column if not exists duration_seconds integer,
    add column if not exists thumbnail_url    text;

-- Loosen body_md: videos can live without a body (we still let authors
-- attach one if they want show notes).
alter table public.academy_articles
    alter column body_md drop not null;

-- Sanity constraint: content_type must be one of the supported kinds.
do $$
begin
    if not exists (
        select 1 from pg_constraint
        where conname = 'academy_articles_content_type_chk'
    ) then
        alter table public.academy_articles
            add constraint academy_articles_content_type_chk
            check (content_type in ('article', 'video'));
    end if;
end $$;

create index if not exists idx_academy_content_type
    on public.academy_articles (content_type);


-- ════ 060_opportunities_attachable_view.sql ════
-- 060_opportunities_attachable_view.sql
--
-- View of opportunities that need attachment analysis. PostgREST's filter
-- language can't express `jsonb_array_length(resource_links) > 0` without
-- false-matching null rows, so the route queries this view instead.

-- jsonb_array_length errors on non-array values — Postgres planner can
-- reorder the AND clauses past the jsonb_typeof guard, so wrap in CASE.
create or replace view public.opportunities_attachable as
select id, notice_id, title, description, resource_links, structured_requirements, ai_win_strategy, posted_date, is_archived
from public.opportunities
where is_archived = false
  and resource_links is not null
  and (structured_requirements->>'_analyzed_attachments_at') is null
  and (case when jsonb_typeof(resource_links) = 'array' then jsonb_array_length(resource_links) else 0 end) > 0;

grant select on public.opportunities_attachable to service_role, authenticated;


-- ════ 061_pg_cron_ingest_and_score.sql ════
