-- ════ 062_govtribe_cache.sql ════
-- 062_govtribe_cache.sql
--
-- Shared cache for GovTribe MCP aggregation responses. Each MCP call costs
-- ~1-2 s (3 round-trips through their session protocol), so we keep the
-- response keyed by (tool_name, args_hash) with a per-tool TTL.

create table if not exists public.govtribe_cache (
    cache_key   text primary key,
    tool_name   text not null,
    args        jsonb not null,
    response    jsonb not null,
    fetched_at  timestamptz not null default now(),
    expires_at  timestamptz not null
);
create index if not exists govtribe_cache_expires_idx on public.govtribe_cache (expires_at);
create index if not exists govtribe_cache_tool_idx on public.govtribe_cache (tool_name);

alter table public.govtribe_cache enable row level security;
drop policy if exists govtribe_cache_service_all on public.govtribe_cache;
create policy govtribe_cache_service_all on public.govtribe_cache
    for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');


-- ════ 062_quick_checker_lead_capture_and_startup_pack.sql ════
-- 062_quick_checker_lead_capture_and_startup_pack.sql
-- Extend company_analyses with explicit lead-capture columns + startup pack purchase state.
-- Also adds the startup_pack_purchases table to track $70 cross-sell purchases via Stripe.

-- ──────────────────────────────────────────────────────────────────────────────
-- 1) Extend company_analyses
-- ──────────────────────────────────────────────────────────────────────────────
alter table public.company_analyses
    add column if not exists lead_phone            text,
    add column if not exists lead_captured_at      timestamptz,
    add column if not exists employee_count        integer,
    add column if not exists annual_revenue_band   text check (annual_revenue_band in
        ('under_1m','1m_5m','5m_25m','25m_plus','prefer_not_to_say')),
    add column if not exists years_in_business     integer,
    add column if not exists startup_pack_unlocked_at        timestamptz,
    add column if not exists startup_pack_stripe_session_id  text,
    add column if not exists utm_source            text,
    add column if not exists utm_medium            text,
    add column if not exists utm_campaign          text;

create index if not exists company_analyses_lead_captured_idx
    on public.company_analyses (lead_captured_at desc nulls last)
    where lead_captured_at is not null;

create index if not exists company_analyses_startup_pack_idx
    on public.company_analyses (startup_pack_unlocked_at desc nulls last)
    where startup_pack_unlocked_at is not null;

-- ──────────────────────────────────────────────────────────────────────────────
-- 2) Startup-pack purchases table (audit trail + asset-access tokens)
-- ──────────────────────────────────────────────────────────────────────────────
create table if not exists public.startup_pack_purchases (
    id                    uuid primary key default gen_random_uuid(),
    analysis_id           uuid references public.company_analyses (id) on delete set null,
    email                 text not null,
    company_name          text,
    amount_paid_cents     integer not null,
    currency              text not null default 'usd',
    stripe_session_id     text unique,
    stripe_payment_intent text,
    access_token          text unique not null default encode(gen_random_bytes(24), 'hex'),
    purchased_at          timestamptz not null default now(),
    refunded_at           timestamptz,
    metadata              jsonb default '{}'::jsonb
);

create index if not exists startup_pack_purchases_email_idx
    on public.startup_pack_purchases (lower(email));

create index if not exists startup_pack_purchases_analysis_idx
    on public.startup_pack_purchases (analysis_id);

-- ──────────────────────────────────────────────────────────────────────────────
-- 3) RLS — keep purchases table service-role-only (no public access)
-- ──────────────────────────────────────────────────────────────────────────────
alter table public.startup_pack_purchases enable row level security;

drop policy if exists "purchases_service_role_all" on public.startup_pack_purchases;
create policy "purchases_service_role_all"
    on public.startup_pack_purchases
    as permissive
    for all
    to service_role
    using (true)
    with check (true);

comment on table public.startup_pack_purchases is
    'Audit log of $70 Startup Pack purchases from the Quick Checker funnel. access_token gates the download page.';


-- ════ 063_status_awaiting_confirmation.sql ════
-- Add `awaiting_confirmation` to the company_analyses.status check constraint.
--
-- The mid-funnel confirmation step (introduced 2026-05-18) writes
-- status='awaiting_confirmation' when the pipeline pauses for the user to
-- review/correct what the crawler found. The status constraint was last
-- updated in migration 021 and never picked up the new value, so the
-- atomic update was being silently rejected by Postgres while the
-- Supabase JS client returned success (we never checked .error). Result:
-- every Quick Checker run sat pinned at status='classifying' forever
-- with no error_message.
--
-- We keep the legacy 'awaiting_naics_selection' value too in case any
-- historical rows still reference it.

ALTER TABLE company_analyses DROP CONSTRAINT IF EXISTS company_analyses_status_check;

ALTER TABLE company_analyses ADD CONSTRAINT company_analyses_status_check
  CHECK (status IN (
    'crawling',
    'enriching',
    'classifying',
    'awaiting_confirmation',
    'awaiting_naics_selection',
    'finding_opportunities',
    'scoring',
    'finding_competitors',
    'generating',
    'complete',
    'error'
  ));


-- ════ 064_opportunity_source.sql ════
-- ============================================================
-- Migration 064: opportunity source tagging
-- ============================================================
-- Why: we're starting to ingest opportunities from multiple data sources
-- beyond SAM.gov — Federal Grants (Grants.gov), and State/Local/Education
-- (SLED) via HigherGov. The downstream UI + scoring engine treats all
-- opportunities the same, but the operator needs to filter / count / debug
-- by source. Without this column, "0 new opps from HigherGov" is silently
-- mixed in with the SAM ingest count.
-- ============================================================

alter table public.opportunities
    add column if not exists source text not null default 'sam'
        check (source in ('sam', 'grants_gov', 'sled', 'sbir', 'state', 'local'));

create index if not exists idx_opportunities_source
    on public.opportunities(source);

comment on column public.opportunities.source is
    'Where this opportunity came from. ''sam''=SAM.gov federal contracts (default for legacy rows), ''grants_gov''=Federal grants via grants.gov, ''sled''=State/Local/Education via HigherGov, ''sbir''=SBIR.gov small-business R&D, ''state''/''local''=direct state portals when added.';


-- ════ 065_government_contacts.sql ════
-- ============================================================
-- Migration 065: government_contacts directory
-- ============================================================
-- Centralized table for government decision-makers (contracting officers,
-- buyers, program managers, SBLOs) sourced from HigherGov /people,
-- SAM.gov POCs, Apollo enrichment, and manual entries. Lets users build
-- targeted outreach lists by agency, role, location, or set-aside.
--
-- Apollo enrichment is layered on top: matching by name + agency domain
-- gives us LinkedIn URL, mobile phone, verified email when available.
-- ============================================================

create table if not exists public.government_contacts (
    id uuid primary key default gen_random_uuid(),

    -- Identity
    name text not null,
    first_name text,
    last_name text,
    title text,

    -- Contact channels (HigherGov often only has email; Apollo fills the rest)
    email text,
    phone text,
    mobile_phone text,
    direct_phone text,
    phone_ext text,
    fax text,
    linkedin_url text,

    -- Agency / employer
    agency_name text,
    agency_abbreviation text,
    agency_key bigint,
    agency_type text,        -- 'Federal' / 'SLED' / 'Local' / 'State' / 'Education'
    agency_domain text,      -- e.g. 'carync.gov' — used for Apollo enrichment
    state text,              -- 2-letter state code when known
    city text,

    -- Source provenance
    source text not null default 'highergov'
        check (source in ('highergov', 'sam_gov', 'apollo', 'manual', 'crawler')),
    contact_type text,       -- 'federal' / 'sled' / 'sblo' / 'co' / 'kp' (key personnel)
    highergov_path text,     -- canonical link back to HigherGov profile
    apollo_id text,

    -- Enrichment metadata
    enriched_at timestamptz,
    enrichment_provider text,   -- 'apollo' / 'manual' / null
    enrichment_quality smallint, -- 0-100 confidence score

    -- LinkedIn intelligence (when scraped/enriched)
    linkedin_headline text,
    linkedin_company text,
    linkedin_years_in_role numeric,   -- tenure in current position
    linkedin_total_experience_years numeric,
    linkedin_skills text[],
    linkedin_education text[],

    -- Outreach state
    last_outreach_at timestamptz,
    outreach_status text check (outreach_status in ('not_contacted','contacted','responded','meeting_booked','do_not_contact','unreachable') or outreach_status is null),
    notes text,

    last_seen_at date,        -- last time the source confirmed this person was active
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

-- Deduplication anchor — same person can appear in multiple sources, but
-- (lower(email)) is the strongest unique key when present. For people
-- without email, the highergov_path is unique per profile.
create unique index if not exists ux_gov_contacts_email
    on public.government_contacts (lower(email))
    where email is not null and email <> '';

create unique index if not exists ux_gov_contacts_highergov_path
    on public.government_contacts (highergov_path)
    where highergov_path is not null;

-- Lookup paths used by the UI + outreach generators
create index if not exists idx_gov_contacts_agency_key
    on public.government_contacts (agency_key)
    where agency_key is not null;

create index if not exists idx_gov_contacts_agency_type
    on public.government_contacts (agency_type);

create index if not exists idx_gov_contacts_state
    on public.government_contacts (state)
    where state is not null;

create index if not exists idx_gov_contacts_outreach_status
    on public.government_contacts (outreach_status)
    where outreach_status is not null;

create index if not exists idx_gov_contacts_last_seen
    on public.government_contacts (last_seen_at desc nulls last);

-- Auto-update updated_at on row changes (standard Supabase pattern)
create or replace function public.tg_government_contacts_updated_at()
returns trigger language plpgsql as $$
begin
    new.updated_at = now();
    return new;
end $$;

drop trigger if exists tg_government_contacts_updated_at on public.government_contacts;
create trigger tg_government_contacts_updated_at
    before update on public.government_contacts
    for each row execute function public.tg_government_contacts_updated_at();

comment on table public.government_contacts is
    'Decision-makers in government — contracting officers, buyers, program managers, SBLOs. Sourced from HigherGov /people, SAM.gov POCs, Apollo enrichment, and the website crawler. Used for targeted outreach generation, BD pipeline contacts, and proposal POCs.';

comment on column public.government_contacts.agency_domain is
    'Email domain of the agency (carync.gov, gsa.gov, etc.). Critical for Apollo /people/match enrichment.';
comment on column public.government_contacts.enrichment_quality is
    'Confidence score 0-100. Higher = more fields verified by enrichment provider. Used to prefer richer records when deduping.';


-- ════ 066_rss_sources.sql ════
-- ============================================================
-- Migration 066: rss_sources seed table for state/local procurement feeds
-- ============================================================
-- Most state/local procurement portals (Bonfire, OpenGov, BidNet, agency-
-- direct RSS) publish opportunities as public RSS. We poll each feed daily,
-- normalize the entries into the existing `opportunities` table, and dedupe
-- by source-prefixed notice_id.
--
-- This table is a per-row config of feeds we know about. Adding a new feed
-- = inserting a row. No code change required.
-- ============================================================

create table if not exists public.rss_sources (
    id uuid primary key default gen_random_uuid(),

    -- Where to fetch
    feed_url text not null unique,

    -- How to namespace + display the opportunities we extract
    source_prefix text not null,            -- 'bonfire-ccsd' → notice_id: 'bonfire-ccsd-<hash>'
    provider text not null                  -- 'bonfire' | 'opengov' | 'agency_direct' | 'other'
        check (provider in ('bonfire', 'opengov', 'periscope', 'bidnet', 'demandstar', 'agency_direct', 'other')),

    -- Display metadata for the UI (helps users understand WHERE the opp came from)
    agency_name text,
    agency_type text default 'SLED',        -- 'SLED' / 'State' / 'Local' / 'Education' / 'Federal'
    state text,                             -- 2-letter state code
    city text,
    website text,                           -- public landing page

    -- Runtime
    enabled boolean not null default true,
    last_fetched_at timestamptz,
    last_status text,                       -- 'ok' / 'http_404' / 'parse_error' / etc
    last_count integer default 0,           -- items in the most recent successful fetch
    consecutive_failures integer not null default 0,

    notes text,
    created_at timestamptz default now(),
    updated_at timestamptz default now()
);

create index if not exists idx_rss_sources_enabled on public.rss_sources(enabled) where enabled = true;
create index if not exists idx_rss_sources_provider on public.rss_sources(provider);
create index if not exists idx_rss_sources_state on public.rss_sources(state) where state is not null;

-- Auto-update updated_at
create or replace function public.tg_rss_sources_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;

drop trigger if exists tg_rss_sources_updated_at on public.rss_sources;
create trigger tg_rss_sources_updated_at
    before update on public.rss_sources
    for each row execute function public.tg_rss_sources_updated_at();

