-- ════ 068_perf_indexes_and_new_agent_tables.sql ════
-- ============================================================
-- Migration 068: perf indexes for enrichment crons + tables for new agents
-- ============================================================
--
-- 1) Five enrichment crons (enrich, backfill_requirements, strategic_scoring,
--    ai_strategy, bulk_enrich_descriptions) were dying with
--    "canceling statement due to statement timeout".  They each filter on
--    `is_archived = false` + a JSONB null/empty check or a description-LIKE.
--    The 59k-row opportunities table has no partial index supporting any of
--    those — every cron scan = full seq scan = ~30s+. Adding partial
--    indexes drops each pick query into ms.
--
-- 2) government_contacts.email had a unique index on `lower(email)` — an
--    expression index that PostgREST's `onConflict: "email"` can't address,
--    so the email-keyed upsert silently no-op'd. The cron has already been
--    switched to dedup by `highergov_path` (commit 3a471061), but a plain
--    unique constraint on the column is still useful for future writers.
--
-- 3) New tables for the additional enrichment agents:
--      - `cron_runs`              telemetry per cron invocation
--      - `past_performance_stats` agency × NAICS win-rate aggregates
--      - `gsa_schedule_holders`   GSA contract holders per Schedule
--      - `wage_determinations`    SCA/DBA wage rates by state/locality
--      - `sec_prime_filings`      latest 10-K/10-Q + earnings-call gist for primes
--      - `gao_protests`           GAO protest decisions + outcomes
--      - `dod_contracts`          DoD daily contract releases (>$7.5M)
-- ============================================================

-- --- 1) Enrichment cron partial indexes ----------------------
-- enrich + bulk_enrich_descriptions: description LIKE 'https://api.sam.gov%'
create index if not exists idx_opps_needs_description_fetch
    on public.opportunities (posted_date desc nulls last)
    where is_archived = false
      and description like 'https://api.sam.gov%';

-- backfill_requirements: raw_json present, structured_requirements missing
create index if not exists idx_opps_needs_requirements_backfill
    on public.opportunities (id)
    where raw_json is not null
      and (structured_requirements is null
           or structured_requirements::text = '{}');

-- strategic_scoring: not archived, scoring missing
create index if not exists idx_opps_needs_strategic_scoring
    on public.opportunities (response_deadline asc nulls last)
    where is_archived = false
      and (strategic_scoring is null
           or strategic_scoring::text = '{}');

-- ai_strategy: not archived, ai_win_strategy missing
create index if not exists idx_opps_needs_ai_strategy
    on public.opportunities (response_deadline asc nulls last)
    where is_archived = false
      and (ai_win_strategy is null
           or ai_win_strategy::text = '{}');


-- --- 2) government_contacts upsert fixes --------------------
-- PostgREST's `onConflict:"col"` reads from pg_constraint, NOT from
-- pg_index. The two unique entries created in migration 065 were
-- `create unique index ... where ...` (partial expression indexes),
-- which Postgres-the-database treats as unique but PostgREST can't
-- match against an ON CONFLICT spec. Result: every upsert from the
-- cron returned "no unique or exclusion constraint matching the ON
-- CONFLICT specification" and 0 rows landed.
--
-- Fix: add real UNIQUE CONSTRAINTS on the two dedup columns. We use
-- non-partial constraints — Postgres treats multiple NULLs as distinct
-- under its default UNIQUE semantics, so contacts without a path or
-- email don't collide.
do $$
begin
    if not exists (
        select 1 from pg_constraint
        where conname = 'uq_gov_contacts_highergov_path'
          and conrelid = 'public.government_contacts'::regclass
    ) then
        alter table public.government_contacts
            add constraint uq_gov_contacts_highergov_path
            unique (highergov_path);
    end if;
exception when duplicate_table or duplicate_object then
    -- ignore race
end $$;

-- For email we keep it case-insensitive via the existing lower(email)
-- index; the new constraint is on the raw column for PostgREST. The
-- HigherGov cron normalizes email to lower() before insert, so the two
-- indexes stay consistent.
do $$
begin
    if not exists (
        select 1 from pg_constraint
        where conname = 'uq_gov_contacts_email'
          and conrelid = 'public.government_contacts'::regclass
    ) then
        alter table public.government_contacts
            add constraint uq_gov_contacts_email
            unique (email);
    end if;
exception when duplicate_table or duplicate_object then
    -- ignore race
end $$;


-- --- 3) cron_runs telemetry table ---------------------------
create table if not exists public.cron_runs (
    id uuid primary key default gen_random_uuid(),
    route text not null,                    -- '/api/cron/<name>'
    started_at timestamptz not null default now(),
    finished_at timestamptz,
    status text,                            -- 'ok' / 'error' / 'timeout' / 'partial'
    rows_in integer,                        -- e.g. fetched/processed
    rows_out integer,                       -- e.g. inserted/updated
    error_message text,
    payload jsonb,                          -- free-form per-route stats
    elapsed_ms integer
);

create index if not exists idx_cron_runs_route_started on public.cron_runs(route, started_at desc);
create index if not exists idx_cron_runs_status on public.cron_runs(status, started_at desc) where status <> 'ok';


-- --- 4) Past-performance stats (agency × NAICS) -------------
create table if not exists public.past_performance_stats (
    agency text not null,
    naics_prefix text not null,             -- 2, 4, or 6-digit
    naics_digits smallint not null check (naics_digits in (2, 4, 6)),
    awards_24mo integer default 0,
    awards_set_aside_8a integer default 0,
    awards_set_aside_hubzone integer default 0,
    awards_set_aside_sdvosb integer default 0,
    awards_set_aside_wosb integer default 0,
    awards_set_aside_small integer default 0,
    awards_fullopen integer default 0,
    unique_winners integer default 0,
    total_obligated numeric(18, 2) default 0,
    median_award_value numeric(18, 2),
    top_winners jsonb,                       -- [{uei, name, awards, total}]
    last_updated timestamptz default now(),
    primary key (agency, naics_prefix)
);
create index if not exists idx_pps_naics on public.past_performance_stats(naics_prefix);


-- --- 5) GSA Schedule holders --------------------------------
-- Table already exists from migration 055. Indexes are already there.
-- Just make sure last_synced (added in this migration) exists; the
-- 055 version used updated_at instead.
alter table public.gsa_schedule_holders
    add column if not exists last_synced timestamptz default now();


-- --- 6) DOL Wage Determinations -----------------------------
create table if not exists public.wage_determinations (
    id uuid primary key default gen_random_uuid(),
    wage_decision_number text not null,       -- e.g. WD-26-1234
    decision_type text,                        -- 'SCA' | 'DBA'
    state text not null,
    county text,
    occupation_title text,
    occupation_code text,                      -- SCA 5-digit
    minimum_hourly_rate numeric(8, 2),
    fringe_benefits numeric(8, 2),
    effective_date date,
    revision_number integer,
    source_url text,
    last_synced timestamptz default now(),
    unique (wage_decision_number, occupation_code, state, county)
);
create index if not exists idx_wd_state_occ on public.wage_determinations(state, occupation_code);


-- --- 7) SEC EDGAR filings for publicly-traded primes --------
create table if not exists public.sec_prime_filings (
    id uuid primary key default gen_random_uuid(),
    cik text not null,                         -- SEC Central Index Key
    ticker text,
    company_name text not null,
    filing_type text not null,                 -- '10-K' | '10-Q' | '8-K' | 'transcript'
    filing_date date not null,
    period_of_report date,
    accession_number text,
    document_url text,
    extracted_themes text[],                   -- e.g. ['DoD IT expansion', 'AI investment']
    extracted_capture_signals jsonb,           -- structured: { agency, intent, time_horizon }
    raw_excerpt text,
    last_synced timestamptz default now(),
    unique (cik, accession_number)
);
create index if not exists idx_sec_cik_date on public.sec_prime_filings(cik, filing_date desc);


-- --- 8) GAO Protest decisions -------------------------------
create table if not exists public.gao_protests (
    id uuid primary key default gen_random_uuid(),
    docket_number text not null unique,        -- e.g. B-422222
    protester text,
    contracting_agency text,
    awardee text,                              -- if known
    decision_date date,
    outcome text,                              -- 'Sustained' | 'Denied' | 'Dismissed' | 'Withdrawn'
    naics_code text,
    psc_code text,
    summary text,
    document_url text,
    raw_json jsonb,
    last_synced timestamptz default now()
);
create index if not exists idx_gao_agency_outcome on public.gao_protests(contracting_agency, outcome);
create index if not exists idx_gao_awardee on public.gao_protests(awardee) where awardee is not null;


-- --- 9) DoD daily contracts release -------------------------
create table if not exists public.dod_contracts (
    id uuid primary key default gen_random_uuid(),
    contract_number text not null,
    recipient_name text,
    recipient_uei text,
    recipient_state text,
    awarding_office text,                      -- e.g. 'Naval Sea Systems Command'
    award_amount numeric(18, 2),
    award_date date,
    period_of_performance text,
    description text,
    naics_code text,
    psc_code text,
    place_of_performance text,
    set_aside text,
    source_url text,
    raw_blob text,
    last_synced timestamptz default now(),
    unique (contract_number, award_date)
);
create index if not exists idx_dod_recipient on public.dod_contracts(recipient_name) where recipient_name is not null;
create index if not exists idx_dod_award_date on public.dod_contracts(award_date desc);


comment on table public.cron_runs is
    'Per-cron-invocation telemetry. Wrap each cron handler in withCronRun() to populate.';
comment on table public.past_performance_stats is
    'Pre-computed agency×NAICS win-rate aggregates from USAspending. Drives strategic_scoring boost.';


-- ════ 069_backlink_pipeline.sql ════
-- ============================================================
-- Migration 069: backlink acquisition pipeline
-- ============================================================
-- Six tables for the end-to-end backlink workflow:
--   1. backlink_prospects  — candidate domains to pursue (Tier 1-5)
--   2. backlink_contacts   — people at each prospect (editors, PR, etc.)
--   3. backlink_outreach   — every email/message sent or drafted
--   4. backlink_monitor    — links we've acquired; auto-checks they stay live
--   5. backlink_agents     — registry of automated agents + last-run state
--   6. backlink_todos      — human tasks (Kanban-style) tied to prospects
-- ============================================================

create extension if not exists pgcrypto;

-- ---- 1) prospects -------------------------------------------
create table if not exists public.backlink_prospects (
  id uuid primary key default gen_random_uuid(),
  domain text not null unique,
  authority_score int,
  trust_score int,
  backlinks_num int,
  refdomains_num int,
  category text,
  -- 'editorial' | 'directory' | 'association' | 'comparison' | 'asset' | 'spam' | 'unknown'
  tier int check (tier between 1 and 5),
  -- 1 = high-value editorial; 5 = spam/disavow
  status text not null default 'discovered',
  -- discovered → researching → contact_found → outreach_drafted
  --   → outreach_sent → replied → won | lost | nurture | disavowed
  refdomain_source text,
  competitor_overlap text[],
  link_target_url text,
  link_anchor_suggestion text,
  pitch_angle text,
  notes text,
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  enrichment_attempted_at timestamptz,
  enrichment_completed_at timestamptz,
  outreach_count int not null default 0,
  reply_received_at timestamptz,
  link_acquired_at timestamptz,
  link_lost_at timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create index if not exists idx_backlink_prospects_status on public.backlink_prospects(status);
create index if not exists idx_backlink_prospects_tier on public.backlink_prospects(tier);
create index if not exists idx_backlink_prospects_score on public.backlink_prospects(authority_score desc nulls last);

-- ---- 2) contacts --------------------------------------------
create table if not exists public.backlink_contacts (
  id uuid primary key default gen_random_uuid(),
  prospect_id uuid not null references public.backlink_prospects(id) on delete cascade,
  full_name text,
  role text,
  email text,
  email_pattern text,
  email_confidence text,
  -- 'verified' | 'guessed' | 'crawled' | 'apollo'
  linkedin_url text,
  twitter text,
  source text,
  created_at timestamptz default now()
);
create index if not exists idx_backlink_contacts_prospect on public.backlink_contacts(prospect_id);
create unique index if not exists idx_backlink_contacts_email_uniq
  on public.backlink_contacts(prospect_id, lower(email))
  where email is not null;

-- ---- 3) outreach --------------------------------------------
create table if not exists public.backlink_outreach (
  id uuid primary key default gen_random_uuid(),
  prospect_id uuid not null references public.backlink_prospects(id) on delete cascade,
  contact_id uuid references public.backlink_contacts(id) on delete set null,
  channel text not null default 'email',
  step int not null default 0,
  subject text,
  body_text text,
  body_html text,
  gmail_draft_id text,
  gmail_compose_url text,
  status text not null default 'drafted',
  -- 'drafted' | 'sent' | 'replied' | 'bounced' | 'cancelled'
  scheduled_for timestamptz,
  sent_at timestamptz,
  replied_at timestamptz,
  generated_by text,
  ai_model text,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create index if not exists idx_backlink_outreach_prospect on public.backlink_outreach(prospect_id);
create index if not exists idx_backlink_outreach_status on public.backlink_outreach(status);

-- ---- 4) monitor (acquired/observed links) ------------------
create table if not exists public.backlink_monitor (
  id uuid primary key default gen_random_uuid(),
  prospect_id uuid references public.backlink_prospects(id) on delete set null,
  source_url text not null,
  target_url text not null,
  anchor_text text,
  is_dofollow boolean,
  is_live boolean not null default true,
  authority_score int,
  first_seen timestamptz not null default now(),
  last_checked timestamptz not null default now(),
  lost_at timestamptz
);
create unique index if not exists idx_backlink_monitor_source_target
  on public.backlink_monitor(source_url, target_url);
create index if not exists idx_backlink_monitor_is_live on public.backlink_monitor(is_live);

-- ---- 5) agents (the automation registry) -------------------
create table if not exists public.backlink_agents (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  display_name text,
  description text,
  cron_schedule text,
  enabled boolean not null default true,
  last_run_at timestamptz,
  last_run_status text,
  last_run_summary jsonb,
  last_run_duration_ms int
);

insert into public.backlink_agents (name, display_name, description, cron_schedule) values
  ('prospect_discovery',
   'Prospect Discovery',
   'Pulls competitor refdomains from Semrush, classifies them (Tier 1-5), dedupes, and inserts new prospects.',
   '0 5 * * 1'),
  ('contact_enrichment',
   'Contact Enrichment',
   'Crawls /contact, /about, /team, and footer of new prospects to extract editor/PR emails. Falls back to email pattern guessing.',
   '0 6 * * 1-5'),
  ('outreach_drafter',
   'Outreach Drafter',
   'Generates personalized pitch emails for prospects with at least one contact. Saves drafts in DB + Gmail compose URL (human clicks Send).',
   '0 7 * * 1-5'),
  ('link_monitor',
   'Link Monitor',
   'Verifies acquired links are still live (HTTP fetch + anchor check). Flags lost links for re-outreach.',
   '0 8 * * 1'),
  ('disavow_generator',
   'Disavow Generator',
   'Reviews capturepilot.com refdomains weekly, flags Moldova/honeypot/spam patterns, exports public/disavow.txt for Google Search Console.',
   '0 9 * * 1')
on conflict (name) do nothing;

-- ---- 6) todos (human tasks) --------------------------------
create table if not exists public.backlink_todos (
  id uuid primary key default gen_random_uuid(),
  prospect_id uuid references public.backlink_prospects(id) on delete cascade,
  title text not null,
  description text,
  assignee text,
  priority text default 'medium',
  status text default 'open',
  due_at timestamptz,
  created_by text,
  created_at timestamptz default now(),
  completed_at timestamptz
);
create index if not exists idx_backlink_todos_status on public.backlink_todos(status);
create index if not exists idx_backlink_todos_prospect on public.backlink_todos(prospect_id);

-- ---- updated_at triggers ----------------------------------
create or replace function public._touch_backlink_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

drop trigger if exists trg_backlink_prospects_updated on public.backlink_prospects;
create trigger trg_backlink_prospects_updated
  before update on public.backlink_prospects
  for each row execute function public._touch_backlink_updated_at();

drop trigger if exists trg_backlink_outreach_updated on public.backlink_outreach;
create trigger trg_backlink_outreach_updated
  before update on public.backlink_outreach
  for each row execute function public._touch_backlink_updated_at();

-- ---- RLS: admin-only (service-role API access) --------------
alter table public.backlink_prospects enable row level security;
alter table public.backlink_contacts  enable row level security;
alter table public.backlink_outreach  enable row level security;
alter table public.backlink_monitor   enable row level security;
alter table public.backlink_agents    enable row level security;
alter table public.backlink_todos     enable row level security;

-- No public policies — only service-role JWT can read/write. Admin API
-- routes use the service key; the admin UI reads via those routes.


-- ════ 070_marketing_leads.sql ════
-- Marketing leads — anonymous email captures from lead-magnet forms on the
-- public website (resource downloads, /lp/* gated guides, exit-intent forms).
-- Distinct from `company_analyses.lead_email` which only fires on Quick Checker.

create table if not exists marketing_leads (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  company text,
  magnet_key text not null,        -- e.g. 'sdvosb-opportunity-map', 'bid-checklist'
  source text,                     -- URL path where the form was submitted
  utm_source text,
  utm_medium text,
  utm_campaign text,
  utm_content text,
  utm_term text,
  referrer text,
  user_agent text,
  ip_hash text,                    -- sha256(ip) — for dedup without storing IP
  resend_synced boolean default false,
  created_at timestamptz default now()
);

create unique index if not exists marketing_leads_email_magnet_idx
  on marketing_leads (lower(email), magnet_key);

create index if not exists marketing_leads_created_idx
  on marketing_leads (created_at desc);

alter table marketing_leads enable row level security;

-- Service-key-only writes (lead capture happens server-side).
create policy "marketing_leads_admin_select" on marketing_leads
  for select using (auth.jwt() ->> 'role' = 'service_role');


-- ════ 071_plan_tiers.sql ════
-- ============================================================
-- Plan-tier feature gating + revenue forecasting + team-accounts
-- foundation. One migration, three coupled additions because they
-- all touch user_profiles and want to ship together so the
-- gating utility can rely on the columns existing.
-- ============================================================

-- 1) plan_tiers — declarative tier definitions. Code references these
-- via the `code` column ('free', 'starter', 'pro', 'enterprise').
-- Limits live in a JSONB so we can add new gates without a migration.

create table if not exists public.plan_tiers (
    id           bigserial primary key,
    code         text not null unique,             -- e.g. 'free', 'starter', 'pro', 'enterprise'
    label        text not null,                     -- 'Free', 'Starter', 'Pro'
    monthly_usd  integer,                            -- null → custom pricing (enterprise/consulting)
    yearly_usd   integer,                            -- null → no annual option
    sort_order   integer not null default 0,
    is_public    boolean not null default true,     -- enterprise sometimes hidden
    limits       jsonb not null default '{}'::jsonb, -- {max_saved_searches: 5, proposals_per_month: 10, api_access: false, ...}
    created_at   timestamptz not null default now()
);

-- Seed the four standard tiers. monthly_usd is null on enterprise →
-- "contact us" pricing.
insert into public.plan_tiers (code, label, monthly_usd, yearly_usd, sort_order, is_public, limits) values
    ('free',       'Free',        0,    null,  10, true,  jsonb_build_object(
        'max_saved_searches', 1,
        'proposals_per_month', 0,
