-- ════ 078_rich_extraction.sql ════
-- Migration 078 — richer extraction targets for state/county/city opps.
--
-- The first-generation extractor (migration 076 + extract-contacts.ts) pulled
-- emails, phones, and URLs from description text. The user's next ask:
--   - estimated value (single value or range)
--   - opportunity class (prime contract vs subcontract vs teaming)
--   - government office mentions (sub-agencies / contracting offices)
--
-- These get populated inline by ingest_rss + ingest_socrata at insert time
-- and backfilled by the backfill_extracted_contacts cron route (extended in
-- the same commit).

alter table opportunities
  add column if not exists estimated_value_min     numeric,
  add column if not exists estimated_value_max     numeric,
  add column if not exists estimated_value_text    text,
  add column if not exists is_subcontract          boolean,
  add column if not exists opportunity_class       text,        -- 'prime' | 'subcontract' | 'teaming'
  add column if not exists extracted_offices       text[];

-- Index for opp-class filtering on the matches page (small selectivity, but
-- worth it for the SLED-heavy queries since prime vs sub is a common filter).
create index if not exists opportunities_opp_class_idx
  on opportunities (opportunity_class)
  where opportunity_class is not null;


-- ════ 079_attachment_url_extraction.sql ════
-- Migration 079 — PDF Phase A: inline attachment-URL extraction.
--
-- SAM.gov rows already track structured attachments in `resource_links` JSONB,
-- but SLED rows (Bonfire / OpenGov / Socrata) have to scrape URLs from the
-- description HTML. This column holds the result of that regex pass so the
-- detail page can render real "Attachments" cards for state/local opps.
--
-- Phase B (per-portal page scraping for portals that don't embed URLs in
-- their RSS descriptions) ships separately — see PDF_DOCUMENT_SCRAPING_PLAN.md.

alter table opportunities
  add column if not exists extracted_attachment_urls text[];


-- ════ 080_ai_keywords.sql ════
-- Migration 080 — AI-extracted keywords for matching + filtering UX.
--
-- The opportunity description is the single richest signal we have about
-- what work the contract covers, but most rows don't have NAICS codes (SLED
-- portals don't publish them) and our regex keyword extractor surfaces
-- stopwords more often than real signal.
--
-- This migration adds an `extracted_keywords text[]` column populated by a
-- cheap LLM (gpt-4o-mini @ $0.0002/row → ~$6 for the full corpus). The
-- matches page renders these as fast click-to-filter chips and the matching
-- scorer can use them as supplemental signal alongside the user's profile
-- keywords.

alter table opportunities
  add column if not exists extracted_keywords         text[],
  add column if not exists keywords_extracted_at      timestamptz,
  add column if not exists keywords_extraction_model  text;

-- GIN index on the array column → fast "contains any of these keywords"
-- filters from the matches UI without a table-scan.
create index if not exists opportunities_extracted_keywords_idx
  on opportunities using gin (extracted_keywords);

-- Marker for the backfill cron to find the punch-list of rows to process.
create index if not exists opportunities_keywords_pending_idx
  on opportunities (keywords_extracted_at)
  where keywords_extracted_at is null;


-- ════ 081_contractor_profile_pages.sql ════
-- Migration 081 — Programmatic SEO contractor pages.
--
-- Per-contractor public landing pages at www.capturepilot.com/contractors/<slug>.
-- Goal: rank in Google for "<contractor name> federal contracts" queries +
-- act as a lead funnel via the "Claim this profile" CTA.
--
-- Pipeline:
--   1. publish_contractor_pages cron picks N contractors with award history
--   2. Apollo enriches company + key contacts
--   3. gpt-4o-mini generates a 2-3 paragraph context summary
--   4. Badge calculator runs nightly: NAICS rank, state rank, Federal Score
--   5. Row inserted with published_at = now(); sitemap includes the slug
--
-- 8K contractors are eligible (those with FPDS award history). Pilot = top 3,
-- then top 500, then 10/day drip via cron. Aggregator pages
-- (/contractors/in/<naics-label>) point at the highest-ranked rows.

create table if not exists contractor_profile_pages (
    id                       uuid primary key default gen_random_uuid(),

    -- Source row
    contractor_uei           text not null unique,        -- references contractors.uei (but no FK — contractors table doesn't have unique constraint on uei)

    -- URL slug (kebab-case, dedupe-safe). Generated from business name.
    slug                     text not null unique,

    -- Canonical content fields
    business_name            text not null,
    primary_naics            text,
    state                    text,
    city                     text,
    cage_code                text,
    sam_registered           boolean,
    sba_certifications       text[],

    -- Award rollup (denormalized from awards/contractors tables for fast page render)
    total_awarded_amount     numeric default 0,
    total_awards_count       int default 0,
    top_agency               text,
    top_agency_amount        numeric,
    awards_by_year           jsonb,                       -- [{year: 2024, value: 1234567, count: 4}, ...]
    top_naics_codes          text[],                      -- top 5 NAICS this contractor has won under

    -- AI / Apollo enrichment payloads
    ai_summary               text,                        -- 2-3 paragraph generated context
    ai_summary_model         text,                        -- 'gpt-4o-mini', 'deepseek-chat', etc.
    apollo_data              jsonb,                       -- raw Apollo company payload
    company_website          text,
    company_linkedin         text,
    company_size_est         text,                        -- '1-10', '11-50', etc.
    industry                 text,
    founded_year             int,

    -- Gamification / badges
    federal_score            int,                         -- 0-100 composite
    score_breakdown          jsonb,                       -- {awards:30, certs:20, ...}
    naics_rank               int,                         -- rank within primary_naics
    state_rank               int,                         -- rank within state
    naics_total              int,                         -- total contractors in this NAICS (for "rank #X of Y")
    state_total              int,
    badges                   text[],                      -- ['top_10_naics', 'multi_agency', 'sdvosb_leader', ...]

    -- Page lifecycle
    is_published             boolean not null default false,
    published_at             timestamptz,
    last_recalc_at           timestamptz,
    view_count               int default 0,
    claim_email              text,                        -- set when contractor "claims" via the funnel
    claimed_at               timestamptz,

    -- Backlink-outreach state (drafted only, NOT sent until user approves template)
    outreach_drafted_at      timestamptz,
    outreach_sent_at         timestamptz,
    outreach_replied_at      timestamptz,
    backlink_url             text,                        -- URL where they linked back to us (manual entry for now)

    created_at               timestamptz not null default now(),
    updated_at               timestamptz not null default now()
);

create index if not exists contractor_profile_pages_published_idx
  on contractor_profile_pages (is_published, published_at desc)
  where is_published = true;

create index if not exists contractor_profile_pages_naics_idx
  on contractor_profile_pages (primary_naics, federal_score desc)
  where is_published = true;

create index if not exists contractor_profile_pages_state_idx
  on contractor_profile_pages (state, federal_score desc)
  where is_published = true;

create index if not exists contractor_profile_pages_score_idx
  on contractor_profile_pages (federal_score desc)
  where is_published = true;

-- Public read policy — contractor pages ARE public landing pages, so anon
-- can read all published rows. Unpublished drafts stay admin-only.
alter table contractor_profile_pages enable row level security;

create policy "public_read_published" on contractor_profile_pages
  for select
  to anon, authenticated
  using (is_published = true);


-- ════ 082_nyc_dg92_socrata.sql ════
-- Add NYC City Record Online (dg92-zbpx) as a Socrata source.
--
-- Per docs/source-analysis/NYC.md: dg92-zbpx is the superset of the narrow
-- tf3b-tk9r dataset we already poll. 103,710 records vs ~3,366; back to 2011.
-- The dataset mixes procurement, personnel changes, public notices, and more
-- in one table — the section_name field discriminates. We pull only
-- "Procurement" rows via the extra_where field_map clause (new in the
-- ingest_socrata client).

insert into socrata_sources (
    portal_host, dataset_id, source_prefix, agency_name, state, city,
    jurisdiction_level, jurisdiction_code, website, field_map, notes
) values (
    'data.cityofnewyork.us', 'dg92-zbpx',
    'socrata-nyc-crol',
    'City of New York (City Record Online)', 'NY', 'New York', 'city', 'NYC',
    'https://data.cityofnewyork.us/d/dg92-zbpx',
    '{
      "title": "short_title",
      "description": "additional_description_1",
      "agency": "agency_name",
      "posted_date": "start_date",
      "response_deadline": "end_date",
      "key_field": "request_id",
      "notice_type_value": "type_of_notice_description",
      "psc_or_category": "category_description",
      "contact_name": "contact_name",
      "contact_phone": "contact_phone",
      "contact_email": "email",
      "extra_where": "section_name=''Procurement''"
    }'::jsonb,
    'NYC City Record Online — procurement subsection only. 103k historical + ongoing daily. Section filter applied via extra_where field-map clause.'
)
on conflict (source_prefix) do nothing;


-- ════ 083_bonfire_json_opt_in.sql ════
-- Bonfire JSON-API ingest opt-in flag.
--
-- The existing /api/cron/ingest_rss path stays the default. Adding a column
-- so we can flip individual tenants to the JSON endpoint (richer data per
-- docs/source-analysis/BONFIRE.md) without a code change.
--
-- Once a tenant has use_json_api=true AND a non-null bonfire_org_id (the
-- numeric OrganizationId scraped from /portal/ HTML), the new
-- /api/cron/ingest_bonfire_json cron picks it up and the RSS cron skips it.

alter table rss_sources
  add column if not exists use_json_api  boolean not null default false,
  add column if not exists bonfire_org_id int;

create index if not exists rss_sources_bonfire_json_idx
  on rss_sources (use_json_api, provider)
  where use_json_api = true;


-- ════ 084_opengov_enable.sql ════
-- Flip the 44 seeded OpenGov tenant rows from enabled=false → enabled=true.
-- The new /api/cron/ingest_opengov cron route uses the OpenGov anonymous
-- JSON API at api.procurement.opengov.com/api/v1 (researched May 2026,
-- verified anonymous + CF-clean). No Playwright needed.
--
-- Idempotent (only flips opengov rows). Operator-trigger only — the
-- 40/40 vercel.json cron cap is already hit so this cron is operator-
-- run via CRON_SECRET, not scheduled.

update rss_sources
   set enabled = true
 where provider = 'opengov'
   and enabled = false;


-- ════ 085_short_desc_sled_fn.sql ════
-- Function the Playwright worker calls to fetch its next batch of SLED rows
-- needing description enrichment. PostgREST can't express char_length() as a
-- filter directly, and the worker's previous JS-side "or empty" check missed
-- the long tail of rows where the upstream RSS landed a stub like
-- "Department: Procurement" (~30-50 chars) — they're non-empty but useless.
--
-- Takes the link-host substring list as a text[] so the worker can update its
-- target portals without a migration.
create or replace function get_sled_rows_needing_enrichment(
    host_patterns text[],
    max_desc_len int default 500,
    batch_size int default 3
)
returns table(
    id uuid,
    title text,
    link text,
    description text
)
language sql
stable
as $$
    select o.id, o.title, o.link, o.description
    from opportunities o
    where o.source = 'sled'
      and o.is_archived = false
      and o.link is not null
      and o.link <> ''
      and (o.description is null or char_length(o.description) < max_desc_len)
      and exists (
          select 1 from unnest(host_patterns) p
          where o.link ilike p
      )
    order by o.last_crawled_at asc nulls first
    limit batch_size;
$$;

grant execute on function get_sled_rows_needing_enrichment(text[], int, int) to service_role;


-- ════ 086_worker_jobs_platform.sql ════
-- The "worker_jobs platform" — turns the codebase into a job queue.
--
-- One table holds every "thing that needs doing" across the system. Both
-- Vercel cron handlers and the Railway Playwright worker poll it for jobs
-- they can handle, claim atomically via UPDATE...FOR UPDATE SKIP LOCKED,
-- process, and write back.
--
-- Companion table portal_cookies caches CF clearance / session cookies per
-- portal host, refreshed periodically by a cookie-warmer worker task.
--
-- Trigger on opportunities INSERT fans out enrichment work the moment any
-- ingest_* cron lands a new row. The bulk-backfill cron in
-- /api/cron/enqueue_backfill seeds the queue with work for every existing
-- under-enriched opp.

-- ---------------------------------------------------------------------------
-- worker_jobs
-- ---------------------------------------------------------------------------
create table if not exists worker_jobs (
    id uuid primary key default gen_random_uuid(),
    task_type text not null,
    -- payload is task-specific; example shapes:
    --   { "opp_id": "...uuid..." }
    --   { "host": "fairfaxcounty.bonfirehub.com" }
    --   { "company_id": "...", "website": "https://..." }
    payload jsonb not null default '{}'::jsonb,
    -- 0-10, higher runs first
    priority int not null default 5 check (priority between 0 and 10),
    -- pending → running → done | failed | skipped
    status text not null default 'pending'
        check (status in ('pending','running','done','failed','skipped')),
    attempts int not null default 0,
    max_attempts int not null default 3,
    created_at timestamptz not null default now(),
    started_at timestamptz,
    finished_at timestamptz,
    error_message text,
    result jsonb,
    -- Optional dedup key: when set, INSERT ON CONFLICT DO NOTHING by this
    -- value prevents duplicate jobs for the same (task_type, target).
    dedup_key text generated always as (task_type || '|' || coalesce(payload->>'opp_id', payload->>'host', payload->>'company_id', '')) stored
);

-- Queue-consumer index: pending jobs by priority then FIFO
create index if not exists worker_jobs_queue_idx
    on worker_jobs (status, priority desc, created_at asc)
    where status = 'pending';
create index if not exists worker_jobs_task_status_idx on worker_jobs (task_type, status);
create unique index if not exists worker_jobs_dedup_active_idx
    on worker_jobs (dedup_key)
    where status in ('pending','running');

alter table worker_jobs enable row level security;
create policy worker_jobs_service_all on worker_jobs for all to service_role using (true) with check (true);

-- ---------------------------------------------------------------------------
-- portal_cookies — CF / session cookie cache per portal host
-- ---------------------------------------------------------------------------
create table if not exists portal_cookies (
    host text primary key,
    cookies jsonb not null,                              -- array of {name, value, domain, path, expires}
    user_agent text not null,                            -- UA the cookies were issued for
    fetched_at timestamptz not null default now(),
    expires_at timestamptz,                              -- earliest cookie expiry
    last_used_at timestamptz,
    use_count int not null default 0
);
create index if not exists portal_cookies_expires_idx on portal_cookies (expires_at);

alter table portal_cookies enable row level security;
create policy portal_cookies_service_all on portal_cookies for all to service_role using (true) with check (true);

-- ---------------------------------------------------------------------------
-- Fan-out trigger — every new opportunity → enrichment jobs queued
-- ---------------------------------------------------------------------------
create or replace function enqueue_opp_enrichment() returns trigger
language plpgsql
as $$
begin
    -- Always-on enrichers
    insert into worker_jobs (task_type, payload, priority) values
        ('classify_naics',          jsonb_build_object('opp_id', new.id), 7),
        ('extract_structured_reqs', jsonb_build_object('opp_id', new.id), 6),
        ('extract_keywords',        jsonb_build_object('opp_id', new.id), 6)
    on conflict (dedup_key) where status in ('pending','running') do nothing;

    -- SLED rows with a portal link → queue Chromium scrape
    if new.source = 'sled' and new.link is not null and char_length(new.link) > 4 then
        insert into worker_jobs (task_type, payload, priority)
        values ('scrape_portal_detail', jsonb_build_object('opp_id', new.id, 'url', new.link), 5)
        on conflict (dedup_key) where status in ('pending','running') do nothing;
    end if;

    -- SAM rows → queue attachment OCR (analyze_match_attachments task type)
    if new.source = 'sam' then
        insert into worker_jobs (task_type, payload, priority)
        values ('analyze_attachments', jsonb_build_object('opp_id', new.id), 4)
        on conflict (dedup_key) where status in ('pending','running') do nothing;
    end if;

    return new;
end;
$$;

drop trigger if exists on_new_opportunity_enrich on opportunities;
create trigger on_new_opportunity_enrich
    after insert on opportunities
    for each row execute function enqueue_opp_enrichment();

-- ---------------------------------------------------------------------------
-- Helper: claim_jobs — atomic batch claim for queue consumers
-- ---------------------------------------------------------------------------
create or replace function claim_jobs(
    p_task_types text[],
    p_batch_size int default 5
)
returns setof worker_jobs
language plpgsql
as $$
begin
    return query
    with claimed as (
        select id
        from worker_jobs
        where status = 'pending'
          and task_type = any(p_task_types)
          and attempts < max_attempts
        order by priority desc, created_at asc
        limit p_batch_size
        for update skip locked
    )
    update worker_jobs j
    set status = 'running',
        started_at = now(),
        attempts = attempts + 1
    from claimed c
    where j.id = c.id
    returning j.*;
end;
$$;

grant execute on function claim_jobs(text[], int) to service_role;

-- ---------------------------------------------------------------------------
-- Helper: finish_job — mark done/failed
-- ---------------------------------------------------------------------------
create or replace function finish_job(
    p_job_id uuid,
    p_status text,
    p_result jsonb default null,
    p_error text default null
)
returns void
language sql
as $$
    update worker_jobs
    set status = p_status,
        finished_at = now(),
        result = coalesce(p_result, result),
        error_message = p_error
    where id = p_job_id;
$$;

grant execute on function finish_job(uuid, text, jsonb, text) to service_role;


-- ════ 087_portal_cookies_blocked.sql ════
-- 087: portal_cookies cooldown column
--
-- When the Playwright worker hits a CF challenge it can't pass, it stamps
-- portal_cookies.last_blocked_at so enqueue_backfill stops re-queueing warm +
-- scrape jobs for that host for ~6h. Without this, the queue burns Railway
-- compute hammering strict-Turnstile tenants every cron tick.

alter table portal_cookies add column if not exists last_blocked_at timestamptz;
create index if not exists portal_cookies_last_blocked_idx on portal_cookies (last_blocked_at);


-- ════ 088_lead_brief.sql ════
-- Lead Brief: AI-generated summary + call script Andre gets emailed for
-- every new marketing lead. See lib/lead-brief.ts for the pipeline.
--
-- One row in marketing_leads owns at most one brief; we overwrite if a
-- re-run produces fresher data (Apollo enrichment can lag the initial
-- insert by minutes).
alter table marketing_leads
add column if not exists lead_brief jsonb,
    add column if not exists lead_brief_sent_at timestamptz,
    add column if not exists lead_brief_status text;
-- lead_brief_status mirrors worker_jobs.status for at-a-glance debugging
-- without a join. Values: 'pending' | 'running' | 'done' | 'failed'.
create index if not exists marketing_leads_brief_status_idx on marketing_leads (lead_brief_status)
where lead_brief_status is not null;
comment on column marketing_leads.lead_brief is 'AI-generated outreach briefing — company snapshot, SAM.gov status, top opportunity matches, fit score, suggested strategy, call script. Generated async by the enrich_lead_brief worker task.';
comment on column marketing_leads.lead_brief_sent_at is 'When the brief email landed in americurial@gmail.com. Null = not sent.';
comment on column marketing_leads.lead_brief_status is 'Latest pipeline status: pending / running / done / failed.';


-- ════ 089_worker_jobs_dedup_lead_id.sql ════
-- Extend worker_jobs.dedup_key to recognize payload.lead_id, so the
-- enrich_lead_brief task (and any future per-lead jobs) gets a unique
-- dedup key instead of collapsing all rows to "enrich_lead_brief|".
--
-- Generated columns can't be edited in place — drop and re-add with the
-- new expression. Stored data is recomputed automatically.

alter table worker_jobs drop column dedup_key;

alter table worker_jobs
    add column dedup_key text generated always as (
        task_type || '|' || coalesce(
            payload->>'opp_id',
            payload->>'host',
            payload->>'company_id',
            payload->>'lead_id',
            ''
        )
    ) stored;

-- The partial unique index on (dedup_key) where status in ('pending','running')
-- was dropped along with the column. Recreate it.
create unique index if not exists worker_jobs_dedup_active_idx
    on worker_jobs (dedup_key)
    where status in ('pending', 'running');


-- ════ 090_security_hardening.sql ════
-- 090: Supabase advisor P0 security hardening
--
-- Closes three ERROR-level + three CRITICAL-WARN findings from the
-- Supabase advisor (audit run 2026-05-27):
--
-- 1. Three SECURITY DEFINER views on `opportunities_*` bypassed RLS
--    entirely. Switching to security_invoker means the view enforces the
--    *querying user's* RLS policies, not the view creator's.
-- 2. Three SECURITY DEFINER functions exposed via PostgREST /rest/v1/rpc/
--    were callable by both `anon` AND `authenticated` roles. That meant
--    any anonymous visitor could fire crons or wipe activity logs. We
--    REVOKE EXECUTE so only the `service_role` (used by trusted backend
--    code with the service key) can call them.

-- ---------------------------------------------------------------------------
-- Views — switch from SECURITY DEFINER to security_invoker
-- ---------------------------------------------------------------------------
alter view public.opportunities_attachable set (security_invoker = on);
alter view public.opportunities_deletable_archived set (security_invoker = on);
alter view public.opportunities_deletable_intelligence set (security_invoker = on);

-- ---------------------------------------------------------------------------
-- Functions — revoke EXECUTE from anon + authenticated
-- ---------------------------------------------------------------------------
revoke execute on function public.trigger_cron_route(text) from anon, authenticated;
revoke execute on function public.rls_auto_enable() from anon, authenticated;
revoke execute on function public.purge_old_activity_log() from anon, authenticated;

-- service_role retains EXECUTE by default (it's superuser-equivalent in
-- the Supabase REST layer). No grant needed.


-- ════ 091_backfill_federal_links.sql ════
-- 091: Backfill missing `link` on federal opportunities
--
-- Audit 2026-05-27: 17,227 of 28,416 active federal opps (60%) had NULL link.
-- The active ingestion code already constructs the link from noticeId (see
-- dashboard/src/app/api/cron/ingest_sam/route.ts line ~206), but historical
-- rows ingested BEFORE that fix landed are stuck with NULL.
--
-- This backfills them in-place: SAM.gov's stable URL for any opportunity is
-- `https://sam.gov/opp/{noticeId}/view`. Idempotent — only touches rows
-- where link IS NULL and notice_id IS NOT NULL.

update public.opportunities
set link = 'https://sam.gov/opp/' || notice_id || '/view'
where source = 'sam'
  and link is null
  and notice_id is not null;


-- ════ 092_api_connectors_add_pdl_vps.sql ════
-- 092: register PDL + SAM_API_KEY_2 + 5 Hostinger VPS services in api_connectors
--
-- Background: health_monitor cron probes every row in api_connectors and
-- alerts on status changes. Before this migration these 7 connectors were
-- invisible to the alert pipeline — a Tika outage or PDL credit exhaustion
-- would have caused silent failures.
--
-- Existing rows (apollo, deepseek, firecrawl, hubspot, meta-*, mistral,
-- openai, resend, sam-gov, stripe, supabase, vercel) are untouched.

insert into public.api_connectors
    (slug, label, env_var_name, category, enabled, rotation_days, docs_url, rotate_url, notes)
values
    -- People Data Labs — Apollo people/match fallback (added 2026-05-27)
    ('pdl', 'People Data Labs',
     'PDL_API_KEY', 'enrichment', true, 365,
     'https://docs.peopledatalabs.com/',
     'https://www.peopledatalabs.com/dashboard/api',
     '1000 calls/mo free tier. Used as Apollo fallback in enrich_apollo_contractors.'),

    -- SAM.gov KEY 2 (entity/contractor scope) — separate quota from KEY 1
    ('sam-gov-contractors', 'SAM.gov (contractors API)',
     'SAM_API_KEY_2', 'data-source', true, 90,
     'https://open.gsa.gov/api/entity-api/',
     'https://sam.gov/data-services/',
     'Dedicated key for entity-information endpoint to avoid quota contention with ingest_sam.'),

    -- Hostinger VPS — Traefik-gated services. Token = the bearer used in
    -- traefik header-matcher rules; tracked separately from URL for clarity.
    ('flaresolverr', 'FlareSolverr (Cloudflare bypass)',
     'FLARESOLVERR_AUTH_TOKEN', 'vps', true, 365,
     'https://github.com/FlareSolverr/FlareSolverr',
     'https://srv1113360.hstgr.cloud/',
     'Hostinger VPS via Traefik. Used for Bonfire CF Turnstile + Salesforce SPA crawl.'),

    ('tika', 'Apache Tika (PDF extraction)',
     'TIKA_AUTH_TOKEN', 'vps', true, 365,
     'https://tika.apache.org/3.0.0/server.html',
     'https://srv1113360.hstgr.cloud/',
     'Hostinger VPS via Traefik. PDF/DOCX text extraction in lib/document-extract.ts.'),

    ('ollama', 'Ollama (local LLM)',
     'OLLAMA_AUTH_TOKEN', 'vps', true, 365,
     'https://github.com/ollama/ollama/blob/main/docs/api.md',
     'https://srv1113360.hstgr.cloud/',
     'Hostinger VPS via Traefik. qwen2.5:7b-instruct loaded. callLLM dispatch when LLM_PROVIDER=ollama.'),

    ('searxng', 'Searxng (meta-search)',
     'SEARXNG_AUTH_TOKEN', 'vps', true, 365,
     'https://docs.searxng.org/',
     'https://srv1113360.hstgr.cloud/',
     'Hostinger VPS via Traefik. Backlink prospect discovery via organic SERPs.'),

    ('crawl4ai', 'Crawl4AI (LLM-friendly crawler)',
     'CRAWL4AI_AUTH_TOKEN', 'vps', true, 365,
