-- ════ 093_public_stats_snapshot.sql ════
-- 093: pre-computed snapshot for /api/public/stats
--
-- /api/public/stats was running 12 parallel count(*) queries on every
-- request (cached at the Vercel edge for 5 min, but the underlying queries
-- still hit Supabase on every revalidation). On large tables like
-- opportunities (60k rows) some of those count(*) calls timed out silently
-- — that's what made `federal_opps` return 0 in production for hours on
-- 2026-05-27 (fixed temporarily with count="estimated" in commit 8ea69f20).
--
-- This pre-computed snapshot replaces all 12 queries with a single SELECT
-- of one row. The snapshot is refreshed every 10 min by a dedicated cron.

create table if not exists public.public_stats_snapshot (
    id           int primary key default 1,
    payload      jsonb not null,
    computed_at  timestamptz not null default now(),
    -- Singleton — exactly one row, ever. Enforced via partial unique +
    -- the explicit default-1 primary key.
    constraint public_stats_snapshot_singleton check (id = 1)
);

-- Seed an empty payload so the first read doesn't 404. The compute cron
-- will overwrite it on first run.
insert into public.public_stats_snapshot (id, payload, computed_at)
values (1, '{}'::jsonb, now())
on conflict (id) do nothing;

-- RLS: payload is anonymous/public anyway (no PII, big-number aggregates)
-- so leave open to anon read. Writes go through service_role.
alter table public.public_stats_snapshot enable row level security;
drop policy if exists public_stats_snapshot_read on public.public_stats_snapshot;
create policy public_stats_snapshot_read
    on public.public_stats_snapshot
    for select
    to anon, authenticated
    using (true);


-- ════ 094_pdf_extract_cache.sql ════
-- 094: hash-based cache for PDF / DOCX extraction results
--
-- analyze_match_attachments re-runs Tika / Mistral OCR per opportunity,
-- but many opps point at the same boilerplate attachments (FAR clause
-- riders, agency-standard cover sheets, etc). With Tika typically 200ms
-- + Mistral ~2-8s of paid-API time per PDF, deduplicating identical bytes
-- saves both wall-clock and money.
--
-- Cache key = sha256 of the raw bytes. Stores the extracted text + which
-- extractor produced it. TTL handled at read-time by the caller (current
-- consumers always want freshness or never want it — no in-table expiry).

create table if not exists public.pdf_extract_cache (
    content_hash    text primary key,
    extracted_text  text not null,
    bytes_size      int  not null,
    source          text not null check (source in ('tika', 'mistral', 'regex')),
    accessed_count  int  not null default 1,
    created_at      timestamptz not null default now(),
    last_accessed   timestamptz not null default now()
);

create index if not exists pdf_extract_cache_last_accessed_idx
    on public.pdf_extract_cache (last_accessed desc);

-- service_role only; no anon/auth access
alter table public.pdf_extract_cache enable row level security;


-- ════ 095_rls_hardening_drop_admin_policies.sql ════
-- 095: drop the "*_admin = USING (true) WITH CHECK (true)" RLS policies
--
-- The Supabase advisor flagged 5 tables with policies that effectively
-- bypassed RLS for every role (USING true + WITH CHECK true, ALL command,
-- no specific role). These were probably leftover from early dev.
--
-- They're redundant because:
--   1. Admin UI calls use SUPABASE_SERVICE_KEY which bypasses RLS entirely
--      (service_role is the Supabase superuser-equivalent in the REST layer).
--   2. Each table also has a properly-scoped per-user policy (user_profile_id
--      tied to auth.uid()) that handles end-user access.
--
-- Dropping them tightens the actual enforcement boundary for signed-in
-- non-admin users without breaking anything (admin operations continue
-- via service key).
--
-- Also: company_analyses had `Allow anonymous insert on company_analyses`
-- with WITH CHECK true on INSERT for anon — intentional for the Quick
-- Checker, but should be rate-limited at the API layer. We DON'T remove
-- it here (it's load-bearing) but flag for future audit (rate-limiter at
-- /api/analyze-company).

drop policy if exists activity_admin     on public.client_activity_log;
drop policy if exists competitors_admin  on public.client_competitors;
drop policy if exists docs_admin         on public.client_documents;
drop policy if exists tasks_admin        on public.client_tasks;
drop policy if exists saved_searches_admin on public.saved_searches;

-- Sanity: make sure RLS is still enabled (admin policy drop doesn't disable RLS,
-- but be explicit).
alter table public.client_activity_log enable row level security;
alter table public.client_competitors  enable row level security;
alter table public.client_documents    enable row level security;
alter table public.client_tasks        enable row level security;
alter table public.saved_searches      enable row level security;


-- ════ 096_n8n_workflow_columns.sql ════
/**
 * Columns required by the 3 n8n workflows on the VPS:
 *   - 01_outreach_drip — tags marketing_leads after touch 1 sent
 *   - 03_opp_deadline_reminders — tags user_pursuits after 24h-before-close reminder
 *
 * Partial indexes target the "not yet processed" subset since both workflows
 * filter on `IS NULL` to avoid double-sending.
 */

alter table public.marketing_leads
  add column if not exists drip_status text,
  add column if not exists drip_last_touch_at timestamptz;

alter table public.user_pursuits
  add column if not exists deadline_reminder_sent_at timestamptz;

create index if not exists idx_marketing_leads_drip_status_null
  on public.marketing_leads(created_at)
  where drip_status is null;

create index if not exists idx_user_pursuits_deadline_reminder_null
  on public.user_pursuits(stage)
  where deadline_reminder_sent_at is null;


-- ════ 097_email_engagement.sql ════
/**
 * Email engagement tracking for Resend deliveries.
 *
 * Resend sends webhooks for delivered / opened / clicked / bounced / complained.
 * We persist every event so /admin/email-tracking can show per-lead engagement.
 *
 * Two pieces:
 *   1. email_events — raw event log, keyed by resend_email_id.
 *   2. marketing_leads.magnet_resend_id / brief_resend_id — pointers from a
 *      lead row to the two messages we sent it, so the admin UI can join
 *      events back to the lead in one query.
 */

create table if not exists public.email_events (
    id uuid primary key default gen_random_uuid(),
    resend_email_id text not null,
    event_type text not null check (event_type in (
        'sent', 'delivered', 'delivery_delayed',
        'opened', 'clicked',
        'bounced', 'complained', 'failed'
    )),
    recipient text,
    link text,
    user_agent text,
    ip text,
    raw jsonb,
    occurred_at timestamptz not null default now(),
    inserted_at timestamptz not null default now()
);

create index if not exists idx_email_events_resend_id
    on public.email_events(resend_email_id);
create index if not exists idx_email_events_type_time
    on public.email_events(event_type, occurred_at desc);
create index if not exists idx_email_events_recipient
    on public.email_events(recipient)
    where recipient is not null;

alter table public.marketing_leads
    add column if not exists magnet_resend_id text,
    add column if not exists brief_resend_id text;

create index if not exists idx_marketing_leads_magnet_resend_id
    on public.marketing_leads(magnet_resend_id)
    where magnet_resend_id is not null;
create index if not exists idx_marketing_leads_brief_resend_id
    on public.marketing_leads(brief_resend_id)
    where brief_resend_id is not null;

alter table public.email_events enable row level security;
-- Service role only; admin UI hits this via /api/admin/* with assertAdmin.


-- ════ 098_alert_autofixes.sql ════
/**
 * Audit log for the auto-healer cron (`/api/cron/self_heal`).
 *
 * Every time the self-heal cron walks open health_alerts, it logs ONE row
 * per attempt here: which recipe ran, what it did, whether it worked.
 * The morning digest reads this table to surface "auto-fixed in last 24h"
 * separately from "needs your attention".
 *
 * Keeping it as a separate audit table (not just resolving the alert)
 * because:
 *   - we want history even after the alert is resolved
 *   - one alert can have multiple fix attempts (recipe runs, fails, escalates)
 *   - distinguishes recipe-driven recovery from self-recovery (Firecrawl
 *     blip resolves itself on next probe → no autofix row)
 */

create table if not exists public.alert_autofixes (
    id uuid primary key default gen_random_uuid(),
    alert_id uuid references public.health_alerts(id) on delete cascade,
    connector_slug text,
    recipe_slug text not null,
    status text not null check (status in ('fixed', 'escalated', 'no_recipe', 'error')),
    action_taken text,
    payload jsonb,
    created_at timestamptz not null default now()
);

create index if not exists idx_alert_autofixes_created on public.alert_autofixes(created_at desc);
create index if not exists idx_alert_autofixes_status on public.alert_autofixes(status, created_at desc);
create index if not exists idx_alert_autofixes_alert on public.alert_autofixes(alert_id);

alter table public.alert_autofixes enable row level security;
-- Service role only; admin UI hits via /api/admin/* with assertAdmin.

-- One-line schema note for the health_alerts side: we use the existing
-- `emailed` boolean to mark alerts the self-healer has acknowledged.
-- A row with emailed=true AND resolved_at=null means "auto-healer
-- acknowledged but couldn't fix — will be in the next morning digest."


-- ════ 099_opps_indexes_and_link_validation.sql ════
/**
 * Two related fixes:
 *
 * 1. Indexes for `n()` count queries in send_daily_digest.
 *    The current query `select count from opportunities where created_at >= yesterday`
 *    silently returns 0 on timeout because there's no index on created_at. That's
 *    why the morning digest has been reporting "0 new opportunities" for days
 *    even though federal grew +600/24h.
 *
 *    Same problem for contractors.created_at and contractor_profile_pages.published_at.
 *
 * 2. link_broken flag for the link-validator cron.
 *    Some SLED opps land with link = `https://<portal>/opportunities/<id>` where
 *    the project_id has rotated or the listing was deleted. We need a way to
 *    flag known-broken links so the frontend can hide the dead button + show a
 *    Google-search fallback instead.
 */

-- ─── Indexes for digest counts ─────────────────────────────────────────────
create index if not exists idx_opportunities_created_at
    on public.opportunities(created_at desc);

create index if not exists idx_opportunities_source_created_at
    on public.opportunities(source, created_at desc);

create index if not exists idx_contractors_created_at
    on public.contractors(created_at desc);

-- ─── Link validation ───────────────────────────────────────────────────────
alter table public.opportunities
    add column if not exists link_broken boolean default false,
    add column if not exists link_last_checked_at timestamptz;

-- Index supports "next 500 to validate" worker queries (oldest checks first,
-- and not-yet-checked rows first).
create index if not exists idx_opportunities_link_check
    on public.opportunities(link_last_checked_at nulls first)
    where source = 'sled' and is_archived = false and link is not null;


-- ════ 100_contractor_ai_analysis.sql ════
/**
 * Caches Ollama-generated capability analysis per contractor.
 *
 * Generated by /api/intelligence/contractor-analysis. Re-renders the
 * Strengths/Weaknesses/Partnership-angle section on contractor/partner/
 * competitor detail pages without re-burning Ollama cycles. 30-day TTL
 * before regeneration so the data stays roughly current as past-awards
 * accumulate.
 */

alter table public.contractors
    add column if not exists capability_summary_ai jsonb,
    add column if not exists capability_summary_refreshed_at timestamptz,
    add column if not exists capability_summary_source text;

-- Index for the "regenerate stale" cron we'll add later — finds contractors
-- whose AI summary is missing or older than 30 days.
create index if not exists idx_contractors_capability_stale
    on public.contractors(capability_summary_refreshed_at nulls first)
    where uei is not null;

-- Index for sorting Contract Winners by award volume (existing column from
-- migration 040 lineage). Speeds up the new /api/contractors/list endpoint.
create index if not exists idx_contractors_award_volume
    on public.contractors(total_award_volume desc nulls last)
    where total_award_volume is not null;

create index if not exists idx_contractors_award_count
    on public.contractors(federal_awards_count desc nulls last)
    where federal_awards_count is not null and federal_awards_count > 0;


-- ════ 101_fpds_piid_unique.sql ════
/**
 * Add a true unique constraint on fpds_awards.piid so the Supabase JS
 * client can use it as an onConflict target.
 *
 * Background: migration 047 created uq_fpds_natural as an EXPRESSION
 * index on (piid, coalesce(referenced_idv, ''), coalesce(modification_number, '')).
 * That's unique but PostgREST/Supabase's onConflict parameter can only
 * take plain column names — expression indexes are invisible to it.
 *
 * Since we migrated FPDS ingestion to USAspending (where Award IDs are
 * globally unique), piid alone is a safe natural key now. The old
 * referenced_idv + modification_number columns stay null for new rows.
 */

-- Drop any duplicate piid rows first (would block the constraint).
-- Keep the most recently fetched row per piid.
delete from public.fpds_awards a
using public.fpds_awards b
where a.piid = b.piid
  and a.fetched_at < b.fetched_at;

alter table public.fpds_awards
    add constraint fpds_awards_piid_unique unique (piid);


-- ════ 102_opportunities_count_indexes.sql ════
/**
 * Make COUNT queries on the 'active opportunities' subset O(log n).
 *
 * Background: compute_public_stats + send_daily_digest run ~10 different
 * COUNT(*) queries every cycle, all scoped to `is_archived = false`
 * (the ~36k-row 'active' subset of the ~60k-row opportunities table).
 * Without matching indexes Postgres falls back to bitmap heap scans that
 * blow past the default statement_timeout (30s) and return 0 silently —
 * which is why federal_opps was reading 0 on the homepage after big
 * SAM ingests even when the rows were physically present.
 *
 * Strategy: 4 PARTIAL indexes scoped to the active subset. Partial indexes
 * are ~40% smaller and skip the archived rows entirely, so even tiny
 * COUNT operations finish well under the timeout. Column ordering in each
 * index is chosen so Postgres's left-prefix matching covers multiple
 * query shapes from one index.
 *
 * After the indexes are built we run ANALYZE so the planner picks them up
 * immediately instead of waiting for the next autovacuum cycle (which can
 * lag 15+ minutes behind a big insert burst).
 */

-- 1. (source, jurisdiction_level) — covers BOTH source-only counts
--    (Federal / SLED / Grants) AND source+jurisdiction counts (SLED state
--    / county / city / district) via left-prefix index scans.
create index if not exists idx_opps_active_source_jur
    on public.opportunities(source, jurisdiction_level)
    where is_archived = false;

-- 2. (source, created_at DESC) — covers the per-source "new in last 24h"
--    breakdown in send_daily_digest (Federal +X / SLED +Y / Grants +Z).
--    The DESC order matches `ORDER BY created_at DESC` patterns on
--    dashboard pages too, so it doubles as a "recent activity" index.
create index if not exists idx_opps_active_source_created
    on public.opportunities(source, created_at desc)
    where is_archived = false;

-- 3. (posted_date DESC) — covers `new_today` on /api/public/stats which
--    filters by posted_date (when SAM published the notice) rather than
--    created_at (when we ingested it). Distinct enough from #2 to need
--    its own index.
create index if not exists idx_opps_active_posted
    on public.opportunities(posted_date desc)
    where is_archived = false;

-- 4. (id) — total active count without any other filters. Tiny index
--    (uuid pk = 16 bytes per row), enables index-only scans for the
--    homepage live counter. The (1)-expression-index variant we tried
--    earlier compiled but the planner couldn't reliably use it for
--    COUNT(*); indexing the pk works in every Postgres version.
create index if not exists idx_opps_active_id
    on public.opportunities(id)
    where is_archived = false;

-- Same problem on contractors — send_daily_digest counts new contractors
-- by created_at and that hit the same silent-0 issue.
create index if not exists idx_contractors_created_at_active
    on public.contractors(created_at desc);

-- Refresh planner stats so Postgres picks the new indexes immediately
-- instead of waiting for autovacuum (which can lag 15+ min after a burst
-- insert and was the proximate cause of the federal_opps=0 reports).
analyze public.opportunities;
analyze public.contractors;
